function M.compose(m,x,y,s,opacity,cfg,measure)
 local w,h=148,184
 for _,item in ipairs({{'P-4 SENATOR',11,170},{m.reserve~=nil and string.format('%03d ROUNDS',m.reserve) or '--- ROUNDS',12,13}}) do
