  for k=0,5 do part(dx+2,39+k*7,5,2,dark,1,'tube-clamp-rib');part(dx+2,40+k*7,5,.5,rim,.4,'tube-clamp-rib') end
 end
 label('RL-77',109,11,silver,false);label(mode,95,10,band,false)
