  for k=0,8 do local width=24-k*2.5;part(66-width/2,73+k*1.8,width,2,{111-k*4,124-k*4,89-k*3},1,'rocket-silhouette') end
  part(64.5,89,3,2,silver,.8,'rocket-silhouette')
