                    ['25aa2fd4643cf4ee']='8ec3026b5f2e579a',
                    ['9f80d67a12a7e40f']='96dfc6542aa22980'})[result.resource_hex]
                if pack_resource or (cfg and reserve_max==0 and not mounted) then
