end)()
HUD.pose=(function()
-- Read-only selected-weapon root pose. Native code is inspected, never invoked.
-- See WEAPON_BINDING.md. Unknown implementations or recycled handles fail closed.
local M={}
local function unhex(s) return (s:gsub('..',function(h)return string.char(tonumber(h,16))end)) end
local pose_prefix=unhex('40534883ec204863da')
local pose_suffix=unhex('488bc84c8b0041ff90e8000000488bcb48c1e10648034828488bc14883c4205bc3')
local resolver_prefix=unhex('48895c24084889742410574883ec20488b35')
local resolver_body=unhex('8bc325ffff3f003b8698000000720433dbeb1c8bc8488b86a0000000c1eb16381c0175eb488b8688000000488b1cc8')
function M.new(backend)
    local r=HUD.memory.new(backend)
    local self={status='not sampled',samples=0}
    function self.snapshot(raw,research,anchor_hash,enumerate)
        assert(raw and raw.binding,'no weapon binding')
        local b=raw.binding;r.reset()
        -- The reader must validate the game build before returning this binding.
        local api=r.p(b.module_base+0x3326308);local unit_api=r.p(api+0x18)
        local getter=r.p(unit_api+0x90);local code=r.read(getter,48)
        assert(code:sub(1,9)==pose_prefix and code:byte(10)==0xe8 and code:sub(15,47)==pose_suffix,'unknown pose getter')
        local resolver=getter+14+r.i(code,10);code=r.read(resolver,116)
        assert(code:sub(1,18)==resolver_prefix and code:sub(0x26,0x54)==resolver_body,'unknown unit resolver')
        local registry=r.p(resolver+0x16+r.i(code,0x12))
        local cap=r.u(r.read(registry+0x98,4),0);assert(cap>0 and cap<=0x400000,'unit capacity')
        local index=b.candidate%0x400000;local generation=math.floor(b.candidate/0x400000)%256
        assert(index>0 and index<cap,'unit index')
        local array=r.p(registry+0x88);local generations=r.p(registry+0xa0)
        assert(r.read(generations+index,1):byte()==generation,'recycled unit')
        local object=r.p(array+index*8)
        assert(r.u(r.read(object+8,4),0)==b.candidate,'unit identity')
        local accessor=r.p(r.p(object)+0xe8)
        assert(r.read(accessor,5)==unhex('488d4160c3'),'unknown scene accessor')
        local nodes=r.u(r.read(object+0x70,4),0);assert(nodes>0 and nodes<=4096,'node count')
        local address=r.p(object+0x88);local bytes=r.read(address,64);local matrix={}
        for i=1,16 do matrix[i]=r.f(bytes,(i-1)*4) end
        for _,i in ipairs({4,8,12}) do assert(math.abs(matrix[i])<1e-5,'matrix affine row') end
        assert(math.abs(matrix[16]-1)<1e-5,'matrix homogeneous component')
        for _,k in ipairs({1,5,9}) do
            local norm=0;for j=0,2 do norm=norm+matrix[k+j]^2 end
            assert(math.abs(norm-1)<.05,'matrix axis scale')
        end
        for _,pair in ipairs({{1,5},{1,9},{5,9}}) do
            local dot=0;for j=0,2 do dot=dot+matrix[pair[1]+j]*matrix[pair[2]+j] end
            assert(math.abs(dot)<.05,'matrix axes')
        end
        for i=13,15 do assert(math.abs(matrix[i])<1e7,'matrix position') end
        local sight,selected_hash;local anchors={}
        -- Optional named anchor; any unavailable or changing table keeps root fallback.
        local sight_ok,sight_value=pcall(function()
            assert(nodes<=128,'sight node limit')
            local hashes=r.p(object+0xa0);local data=r.read(hashes,nodes*4)
            for n=0,nodes-1 do
                local hash=r.u(data,n*4)
                if enumerate then anchors[#anchors+1]={index=n,hash=string.format('%08x',hash)} end
                if raw.resource_hex=='6cfcc7f8801a0266' and enumerate then
                    local nb=r.read(address+n*64,64);local rel={}
                    for aa=0,2 do for bb=0,2 do
                        local dot=0;for kk=0,2 do dot=dot+matrix[aa*4+kk+1]*r.f(nb,(bb*4+kk)*4) end
                        rel[#rel+1]=dot
                    end end
                    self.melta_relative=self.melta_relative or {};local prev=self.melta_relative[hash]
                    if prev then
                        local delta=0;for ii=1,9 do delta=math.max(delta,math.abs(rel[ii]-prev[ii])) end
                        self.melta_changes=self.melta_changes or {};self.melta_changes[hash]=math.max(self.melta_changes[hash] or 0,delta)
                    else self.melta_relative[hash]=rel end
                end
                if hash==(anchor_hash or 0x4d25685a) or (not anchor_hash and hash==0x527c9c73 and selected_hash~=0x4d25685a) then
                    local pose=r.read(address+n*64,64);local delta={}
                    for j=1,3 do delta[j]=r.f(pose,(11+j)*4)-matrix[12+j];assert(math.abs(delta[j])<5,'sight bounds') end
                    assert(r.p(object+0xa0)==hashes and r.read(hashes,nodes*4)==data,'sight table changed')
                    local node_matrix={}
                    for j=1,16 do node_matrix[j]=r.f(pose,(j-1)*4) end
                    for _,k in ipairs({1,5,9}) do
                        local norm=0;for j=0,2 do norm=norm+node_matrix[k+j]^2 end
                        assert(math.abs(norm-1)<.05,'attachment axis scale')
                    end
                    local result={index=n,matrix=node_matrix}
                    for axis,k in ipairs({1,5,9}) do
                        local v=0;for j=1,3 do v=v+delta[j]*matrix[k+j-1] end
                        result[({'x','y','z'})[axis]]=v
                    end
                    sight=result
                    selected_hash=hash
                end
            end
        end)
        if not sight_ok then sight=nil;anchors={} end
        local node_parts
        if research then
            assert(nodes<=128,'research node limit')
            node_parts={{name='weapon_identity',address=b.record,data=r.read(b.record,24)},{name='weapon_scene_header',address=object+0x60,data=r.read(object+0x60,128)}}
            -- Native node lookup (+0x6d8) uses scene+0x40; parent lookup
            -- (+0x500) uses scene+0x38. Scene accessor returns object+0x60.
            local node_hashes=r.p(object+0xa0);local parents=r.p(object+0x98)
            node_parts[#node_parts+1]={name='weapon_scene_node_hashes',address=node_hashes,data=r.read(node_hashes,nodes*4)}
            node_parts[#node_parts+1]={name='weapon_scene_parents',address=parents,data=r.read(parents,nodes*4)}
            assert(r.p(object+0xa0)==node_hashes and r.p(object+0x98)==parents and r.u(r.read(object+0x70,4),0)==nodes,'scene tables changed')
            local scene_resource=r.p(object+0x68)
            node_parts[#node_parts+1]={name='weapon_scene_resource',address=scene_resource,data=r.read(scene_resource,512)}
            for first=0,nodes-1,64 do
                local at=address+first*64
                node_parts[#node_parts+1]={name='weapon_nodes_'..first,address=at,data=r.read(at,math.min(64,nodes-first)*64)}
            end
            if research~='avatar' then
            local resource_getter=r.p(r.p(object)+0x1b0)
            local resource_code=r.read(resource_getter,64)
            node_parts[#node_parts+1]={name='weapon_resource_accessor',address=resource_getter,data=resource_code}
            assert(resource_code:sub(1,8)==unhex('488b8178010000c3'),'unknown weapon resource accessor')
            local resource=r.p(object+0x178);local names=r.p(resource+0x28)
            local header=r.read(names,32);local count=r.u(header,0x14);local offset=r.u(header,0x18)
            node_parts[#node_parts+1]={name='weapon_resource_header',address=resource,data=r.read(resource,256)}
            node_parts[#node_parts+1]={name='weapon_lookup_table_header',address=names,data=header}
            assert(count<=128 and offset<0x100000,'lookup table bounds')
            if count>0 then node_parts[#node_parts+1]={name='weapon_lookup_hashes',address=names+offset,data=r.read(names+offset,count*4)} end
            assert(r.p(object+0x178)==resource and r.p(resource+0x28)==names,'weapon resource changed')
            node_parts[#node_parts+1]={name='weapon_object_header',address=object,data=r.read(object,96)}
            if research=='api' then
                for off=0x4f8,0x700,8 do
                    local ok,entry=pcall(function()local fn=r.p(unit_api+off);return {name=string.format('weapon_api_%x',off),address=fn,data=r.read(fn,128)} end)
                    if ok then node_parts[#node_parts+1]=entry end
                end
            end
            local lookup=r.p(unit_api+0x3b0)
            node_parts[#node_parts+1]={name='weapon_node_lookup_code',address=lookup,data=r.read(lookup,512)}
            end
        end
        -- Revalidate both ends after the read; no persistent entity/matrix pointer cache.
        local record=r.read(b.record,24)
        assert(r.u(record,8)==raw.id and r.u(record,12)==b.candidate and r.u(record,16)==raw.unit_ref,'weapon changed')
        assert(r.read(generations+index,1):byte()==generation and r.p(array+index*8)==object,'unit recycled during read')
        assert(r.u(r.read(object+8,4),0)==b.candidate and r.p(object+0x88)==address,'pose owner changed')
        return {id=raw.id,resource_hex=raw.resource_hex,candidate=b.candidate,node_count=nodes,
            node_parts=node_parts,sight=sight,anchors=anchors,matrix=matrix,x=matrix[13],y=matrix[14],z=matrix[15]}
    end
    function self.poll(raw,anchor_hash,enumerate)
        local ok,value=pcall(self.snapshot,raw,nil,anchor_hash,enumerate)
        if not ok then self.status=tostring(value);return nil end
        self.status='verified root pose';self.samples=self.samples+1;return value
    end

    return self
end
return M

end)()
HUD.camera_mode=(function()
-- Read the game's accepted first-person toggle, never physical key presses.
-- The native toggle resolves the local player and changes one byte at +0x2EC.
local M={}
local signatures={{0xa42a74,'4c8b0ded398e02'},{0xa42b1f,'4138bc24ec020000'},{0xa42b2a,'41888424ec020000'}}
function M.read(backend,raw)
    local ok,value=pcall(function()
        assert(raw and raw.binding,'no current weapon identity')
        local r=HUD.memory.new(backend);r.reset()
        local base=raw.binding.module_base
        for _,s in ipairs(signatures) do
            local expected=s[2]:gsub('..',function(h)return string.char(tonumber(h,16))end)
            assert(r.read(base+s[1],#expected)==expected,'unknown first-person control binding')
        end
        local player=r.p(base+HUD.layouts.player)
        assert(r.u(r.read(player+0x3a8,4),0)==raw.avatar_unit_ref,'avatar changed')
        local local_record=r.p(player+0xe8);local local_data=r.read(local_record,24)
        assert(local_data:byte(21)%2==1 and r.map(player+0xd0,r.u(local_data,8),64)==0,'not local player slot')
        local flag=r.read(player+0x2ec,1):byte()
        assert(flag==0 or flag==1,'invalid first-person state')
        assert(r.p(base+HUD.layouts.player)==player and r.p(player+0xe8)==local_record and
            r.u(r.read(player+0x3a8,4),0)==raw.avatar_unit_ref,'avatar changed during mode read')
        return flag==1
    end)
    if ok then return value,'game first-person state' end
    return nil,tostring(value)
end
-- Observed active shoulder state, read through the native character flag owner.
function M.read_shoulder(backend,raw,aiming)
    local ok,value=pcall(function()
        assert(raw and raw.binding,'no current weapon identity')
        local r=HUD.memory.new(backend);r.reset()
        local base=raw.binding.module_base
        for _,s in ipairs({{0xa4604c,'4c8b15cd0c8e02'},{0xa460da,'4869c138120000'},{0xa460e1,'4a8b841088e8530048c1e82a2401'}}) do
            local expected=s[2]:gsub('..',function(h)return string.char(tonumber(h,16))end)
            assert(r.read(base+s[1],#expected)==expected,'unknown shoulder control binding')
        end
        local player=r.p(base+HUD.layouts.player)
        assert(r.u(r.read(player+0x3a8,4),0)==raw.avatar_unit_ref,'avatar changed')
        local manager=r.p(base+0x3326d20)
        local index=r.map(manager+0xf8,raw.binding.avatar_id,65536)
        assert(index and index<16,'no bounded shoulder slot')
        local identity=r.p(manager+0x110+index*8)
        assert(identity==raw.binding.avatar_record,'shoulder avatar identity mismatch')
        local flag=r.read(manager+0x53e88d+index*0x1238,1):byte()
        local aim
        if aiming then
            local flags=r.read(manager+0x53e880+index*0x1238,16)
            aim=math.floor(flags:byte(11)/4)%2==1
            assert(aim==(math.floor(flags:byte(16)/32)%2==1),'aiming flags disagree')
            assert(r.read(manager+0x53e880+index*0x1238,16)==flags,'aiming flags changed')
        end
        assert(r.p(base+0x3326d20)==manager and r.p(manager+0x110+index*8)==identity and
            r.p(base+HUD.layouts.player)==player and r.u(r.read(player+0x3a8,4),0)==raw.avatar_unit_ref,'shoulder owner changed')
        if aiming then return aim end
        return math.floor(flag/4)%2==1
    end)
    if ok then return value,'game shoulder state' end
    return nil,tostring(value)
end
function M.read_aiming(backend,raw) return M.read_shoulder(backend,raw,true) end
return M

end)()
HUD.projection=(function()
-- Diagnostic world-to-screen projection. Reads data only; no engine calls.
-- Initial scope: perspective camera with identity local camera offset.
local M={}
local function unhex(s)return (s:gsub('..',function(h)return string.char(tonumber(h,16))end))end
local function validate(m,fov,aspect)
    assert(fov>.05 and fov<3.1 and aspect>.1 and aspect<10,'projection dimensions')
    for i=1,16 do assert(type(m[i])=='number' and m[i]==m[i] and math.abs(m[i])<1e7,'camera matrix finite') end
    for _,k in ipairs({1,5,9}) do
        local n=m[k]^2+m[k+1]^2+m[k+2]^2;assert(math.abs(n-1)<.01,'camera axis scale')
    end
    for _,p in ipairs({{1,5},{1,9},{5,9}}) do
        local a,b=p[1],p[2];assert(math.abs(m[a]*m[b]+m[a+1]*m[b+1]+m[a+2]*m[b+2])<.01,'camera axes')
    end
    assert(math.abs(m[4])+math.abs(m[8])+math.abs(m[12])+math.abs(m[16]-1)<1e-5,'camera affine')
end
local function project_validated(m,x,y,z,fov,aspect,near)
    local dx,dy,dz=x-m[13],y-m[14],z-m[15]
    local right=dx*m[1]+dy*m[2]+dz*m[3]
    local depth=dx*m[5]+dy*m[6]+dz*m[7]
    local up=dx*m[9]+dy*m[10]+dz*m[11]
    if depth<=math.max(near,.0001) then return nil,'behind camera or near plane' end
    local t=math.tan(fov*.5)
    local nx,ny=.5+.5*right/(depth*t*aspect),.5+.5*up/(depth*t)
    if nx~=nx or ny~=ny or nx<0 or nx>1 or ny<0 or ny>1 then return nil,'outside viewport' end
    return {x=nx,y=ny,depth=depth},'projected weapon root'
end
-- Validate this immutable frame snapshot once, rather than once per glyph corner.
function M.project(m,x,y,z,fov,aspect,near)
    validate(m,fov,aspect)
    return project_validated(m,x,y,z,fov,aspect,near)
end
function M.projector(m,fov,aspect,near)
    validate(m,fov,aspect)
    return function(x,y,z)return project_validated(m,x,y,z,fov,aspect,near) end
end
-- Invert the camera projection of a planar panel without clipping its corners.
-- u runs right and v runs down. This also handles partially offscreen panels.
function M.panel_inverse(camera,fov,aspect,x,y,z,ux,uy,uz,vx,vy,vz)
    local t=math.tan(fov*.5)
    local function terms(px,py,pz)
        local r=px*camera[1]+py*camera[2]+pz*camera[3]
        local d=px*camera[5]+py*camera[6]+pz*camera[7]
        local up=px*camera[9]+py*camera[10]+pz*camera[11]
        return .5*d+r/(2*t*aspect),.5*d-up/(2*t),d
    end
    local a,d,g=terms(ux,uy,uz)
    local b,e,h=terms(vx,vy,vz)
    local c,f,i=terms(x-camera[13],y-camera[14],z-camera[15])
    local aa,ab,ac=e*i-f*h,c*h-b*i,b*f-c*e
    local ba,bb,bc=f*g-d*i,a*i-c*g,c*d-a*f
    local ca,cb,cc=d*h-e*g,b*g-a*h,a*e-b*d
    local determinant=a*aa+b*ba+c*ca
    local extent=math.max(math.abs(a),math.abs(b),math.abs(c),math.abs(d),math.abs(e),math.abs(f),math.abs(g),math.abs(h),math.abs(i))
    if extent==0 or math.abs(determinant)<1e-12*extent^3 then return nil end
    local norm=math.max(math.abs(ca),math.abs(cb),math.abs(cc))
    if norm==0 then return nil end
    return aa/norm,ab/norm,ac/norm,ba/norm,bb/norm,bc/norm,ca/norm,cb/norm,cc/norm
end

-- Clip a convex world-space polygon against this snapshot's perspective frustum.
-- UVs are interpolated at intersections before the perspective divide.
function M.clip_polygon(m,vertices,fov,aspect,near,scratch)
    assert(fov>.05 and fov<3.1 and aspect>.1 and aspect<10,'projection dimensions')
    local t=math.tan(fov*.5);local n=math.max(near,.0001)
    local polygon=scratch and scratch.camera or {}
    for i,v in ipairs(vertices) do
        local dx,dy,dz=v.x-m[13],v.y-m[14],v.z-m[15]
        local point=polygon[i] or {};polygon[i]=point
        point.r=dx*m[1]+dy*m[2]+dz*m[3];point.d=dx*m[5]+dy*m[6]+dz*m[7]
        point.u=dx*m[9]+dy*m[10]+dz*m[11];point.s=v.s or 0;point.v=v.v or 0
    end
    for i=#polygon,#vertices+1,-1 do polygon[i]=nil end
    -- Most HUD pieces are fully inside the snapshot frustum. Keep their
    -- vertices unchanged instead of allocating five clipping work lists.
    local fully_inside=true
    for _,p in ipairs(polygon) do
        if p.d<n or p.d*t*aspect+p.r<0 or p.d*t*aspect-p.r<0 or p.d*t+p.u<0 or p.d*t-p.u<0 then fully_inside=false;break end
    end
    if not fully_inside then
    local planes={function(p)return p.d-n end,function(p)return p.d*t*aspect+p.r end,
        function(p)return p.d*t*aspect-p.r end,function(p)return p.d*t+p.u end,function(p)return p.d*t-p.u end}
    for _,distance in ipairs(planes) do
        if #polygon==0 then break end
        local clipped={};local previous=polygon[#polygon];local pd=distance(previous)
        for _,current in ipairs(polygon) do
            local cd=distance(current)
            if (pd>=0)~=(cd>=0) then
                local ratio=pd/(pd-cd);local intersection={}
                for _,key in ipairs({'r','d','u','s','v'}) do intersection[key]=previous[key]+(current[key]-previous[key])*ratio end
                clipped[#clipped+1]=intersection
            end
            if cd>=0 then clipped[#clipped+1]=current end
            previous,pd=current,cd
        end
        polygon=clipped
    end
    end
    local result=scratch and fully_inside and scratch.result or {}
    for i,p in ipairs(polygon) do
        local point=result[i] or {};result[i]=point
        point.x=math.max(0,math.min(1,.5+.5*p.r/(p.d*t*aspect)))
        point.y=math.max(0,math.min(1,.5+.5*p.u/(p.d*t)));point.depth=p.d;point.s=p.s;point.v=p.v
    end
    for i=#result,#polygon+1,-1 do result[i]=nil end
    return result
end
-- Screen-relative seed only; this does not establish model clearance.
function M.auto_mount(camera,p,fov,aspect,near)
    local dx,dy,dz=p.x-camera[13],p.y-camera[14],p.z-camera[15]
    local depth=dx*camera[5]+dy*camera[6]+dz*camera[7]
    depth=math.max(near+.15,math.max(.55,depth))
    local nx=(p.first_person or p.left_shoulder) and .42 or .58
    local right=(nx-.5)*2*depth*math.tan(fov*.5)*aspect
    local up=-.04*depth*math.tan(fov*.5)
    local x=camera[13]+camera[5]*depth+camera[1]*right+camera[9]*up-p.x
    local y=camera[14]+camera[6]*depth+camera[2]*right+camera[10]*up-p.y
    local z=camera[15]+camera[7]*depth+camera[3]*right+camera[11]*up-p.z
    local m=p.matrix
    return {x=x*m[1]+y*m[2]+z*m[3],y=x*m[5]+y*m[6]+z*m[7],z=x*m[9]+y*m[10]+z*m[11]}
end
function M.left_shoulder(previous,lateral,first_person)
    if first_person or not lateral then return false end
    return lateral>(previous and 0.4 or 0.7)
end
function M.first_person(previous,distance,fov)
    if not distance or not fov then return false end
    if previous then return distance<0.95 and fov<1.45 end
    return distance<0.75 and fov<1.3
end
function M.new(backend)
    local r=HUD.memory.new(backend);local self={status='not sampled'}
    function self.snapshot(base,pose,aspect)
        r.reset()
        local api=r.p(base+0x3326308);local camera_api=r.p(api+0x20)
        local getter=r.p(camera_api+0xf8)
        assert(r.read(getter,10)==unhex('48895c2408574883ec60'),'unknown projection wrapper')
        local call=r.read(getter+0x132,5);assert(call:byte()==0xe8,'unknown projection call')
        local impl=getter+0x137+r.i(call,1)
        assert(r.read(impl,16)==unhex('488bc448895808488968104889701857'),'unknown projection implementation')
        assert(r.read(impl+0x62,20)==unhex('488b471848c1e206418be948035028e80a951500'),'unknown camera scene layout')
        local state=r.p(base+0x346d560);local camera=r.p(state);local b=r.read(camera,160)
        local scene=r.p(camera+0x18);local index=r.u(b,0x20)
        assert(index<4096,'camera node index')
        assert(r.u(b,0x30)==1 and r.u(b,0x50)==0,'unsupported camera projection mode')
        local near,fov=r.f(b,0x28),r.f(b,0x34)
        assert(near>0 and near<10,'camera near plane')
        -- Nonidentity local offsets require a separately verified inverse transform.
        for _,o in ipairs({0x80,0x84,0x88,0x90,0x94,0x98,0x48,0x4c}) do
            assert(math.abs(r.f(b,o))<1e-6,'camera local offset unsupported')
        end
        assert(math.abs(math.abs(r.f(b,0x8c))-1)<1e-6,'camera local rotation unsupported')
        local array=r.p(scene+0x28);local data=r.read(array+index*64,64);local matrix={}
        for i=1,16 do matrix[i]=r.f(data,(i-1)*4) end
        assert(r.p(base+0x346d560)==state and r.p(state)==camera and r.p(camera+0x18)==scene
            and r.u(r.read(camera+0x20,4),0)==index and r.p(scene+0x28)==array,'camera changed during read')
        self.native_camera=camera;self.native_getter=getter
        self.camera_matrix=matrix;self.camera_near=near;self.camera_aspect=aspect
        self.camera_distance=math.sqrt((pose.x-matrix[13])^2+(pose.y-matrix[14])^2+(pose.z-matrix[15])^2)
        self.camera_fov=fov
        self.camera_lateral=(pose.x-matrix[13])*matrix[1]+(pose.y-matrix[14])*matrix[2]+(pose.z-matrix[15])*matrix[3]
        return M.project(matrix,pose.x,pose.y,pose.z,fov,aspect,near)
    end
    function self.native_point(x,y,z)
        if not backend.project_camera or not self.native_camera or not self.native_getter then return nil end
        local ok,a,b,d=pcall(backend.project_camera,self.native_getter,self.native_camera,x,y,z)
        if not ok or type(a)~='number' or a~=a or b~=b or d~=d then return nil end
        return {x=a,y=b,depth=d}
    end
    function self.poll(base,pose,aspect)
        if not base or not pose then self.status='no weapon pose';return nil end
        self.native_camera=nil;self.native_getter=nil
        self.camera_matrix=nil;self.camera_near=nil;self.camera_aspect=nil
        self.camera_distance=nil;self.camera_fov=nil;self.camera_lateral=nil
        local ok,result,status=pcall(self.snapshot,base,pose,aspect)
        self.status=ok and status or tostring(result)
        return ok and result or nil
    end
    return self
end
return M

end)()
HUD.anchor=(function()
-- Read the native crosshair controller AFTER the game's update.
-- Layout independently traced from hud_crosshair -> native update -> screen XY.
-- Never invokes game functions or writes game memory.
local M={}
local SPEC={
    manager=0x346D538,camera=0x346D560,hud=0x24E340,crosshair=0x19AAF8,
    signatures={
        {0x12F53AF,'488b2d82811702'},
        {0x12F588F,'488d8d40e32400448bc60f28cee8af63ffffeb17'},
        {0x12EBDF4,'498d8ef8aa1900448bc30f28cfe85aa74c00'},
        {0x17B6718,'488b0521fcb6018b8830c50a00'},
        {0x17B6FF5,'f20f1008488b4424500f28c1f3410f118f88200000f30f5cce0fc6c055f3410f11878c200000'},
        {0x17B7050,'f30f594010498bcf8b542424f30f114583488b44245849898790200000'},
        {0x144C370,'488b81f00000004885c074130f1f4000488bc8488b80f00000004885c075f1488bc1c3'}
    }
}
M.spec=SPEC
function M.new(backend)
    local r=HUD.memory.new(backend)
    local base,validated,failed;local self={status='not sampled',samples=0}
    local function validate()
        r.reset();base=assert(backend.module('game.dll'),'game.dll not loaded')
        local d=r.read(base,64);assert(d:sub(1,2)=='MZ','DOS signature')
        local offset=r.u(d,0x3c);assert(offset<0x100000,'PE offset')
        local h=r.read(base+offset,0x80)
        assert(h:sub(1,4)=='PE\0\0' and HUD.layouts.stamps[r.u(h,8)]==r.u(h,0x50),'unsupported anchor build')
        for _,s in ipairs(SPEC.signatures) do
            local expected=s[2]:gsub('..',function(hex)return string.char(tonumber(hex,16))end)
            assert(r.read(base+s[1],#expected)==expected,string.format('anchor signature %X',s[1]))
        end
        validated=true
    end
    local function optional_pointer(a)
        local b=r.read(a,8);local p=r.u(b,0)+r.u(b,4)*2^32
        if p==0 then return nil end
        assert(p>=65536 and p<2^47,'anchor pointer');return p
    end
    local function snapshot()
        r.reset()
        local manager=r.p(base+SPEC.manager)
        local hud=manager+SPEC.hud
        if r.read(hud+0x58,1):byte(1)==0 or r.read(hud+0x21f5b0,1):byte(1)==0 then return nil,'native HUD inactive' end
        local control=hud+SPEC.crosshair
        local b=r.read(control+0x2080,24)
        local state=r.u(b,0)
        if state==1 then return nil,'native reticle hidden' end
        assert(state>=2 and state<=4,'invalid reticle state')
        local pixel_x,pixel_y=r.f(b,8),r.f(b,12)
        local dx,dy=r.f(b,16),r.f(b,20)
        -- This is the same bounded parent walk as native UI root lookup 144C370.
        local root=control;local visited={};local finished=false
        for _=1,32 do
            assert(not visited[root],'UI parent cycle');visited[root]=true
            local parent=optional_pointer(root+0xf0)
            if not parent then finished=true;break end
            root=parent
        end
        assert(finished,'UI parent depth')
        local size=r.read(root+0xc,8);local width,height=r.f(size,0),r.f(size,4)
        assert(width>=64 and width<=32768 and height>=64 and height<=32768,'UI root dimensions')
        local camera=r.p(base+SPEC.camera);local offset=r.read(camera+0xdc,8)
        local cx,cy=r.f(offset,0),r.f(offset,4)
        assert(math.abs(cx)<=1 and math.abs(cy)<=1,'camera screen offset')
        -- Native: local = (screen - 0.5*viewport*(1+camera_offset))/viewport * UI_size.
        -- Invert it to normalize without confusing render-scale pixels with output pixels.
        local nx,ny=0.5*(1+cx)+dx/width,0.5*(1+cy)+dy/height
        assert(nx>=-1 and nx<=2 and ny>=-1 and ny<=2,'reticle coordinates out of range')
        assert(math.abs(pixel_x)<=65536 and math.abs(pixel_y)<=65536,'screen position out of range')
        assert(r.p(base+SPEC.manager)==manager and r.u(r.read(control+0x2080,4),0)==state,'reticle changed during read')
        self.samples=self.samples+1;self.native_state=state
        self.pixel_x,self.pixel_y,self.dx,self.dy=pixel_x,pixel_y,dx,dy
        self.min_x=math.min(self.min_x or nx,nx);self.max_x=math.max(self.max_x or nx,nx)
        self.min_y=math.min(self.min_y or ny,ny);self.max_y=math.max(self.max_y or ny,ny)
        return {x=math.max(0,math.min(1,nx)),y=math.max(0,math.min(1,1-ny)),visible=true},'native crosshair'
    end
    function self.poll()
        if failed then return nil end
        if not validated then
            local ok,err=pcall(validate)
            if not ok then self.status=tostring(err);failed=not self.status:find('game.dll not loaded',1,true);return nil end
        end
        local ok,result,status=pcall(snapshot)
        self.status=ok and status or tostring(result)
        return ok and result or nil
    end
    return self
end
return M

end)()
HUD.view=(function()
local M={}
function M.new(sr)
    local gui,world;local ids={};local G,W,A=sr.Gui,sr.World,sr.Application
    local font='core/performance_hud/debug'
    local self={}
    local blur;local probe_frames=0
    local candidates={'content/ui/shared/material/gui_blur','content/ui/shared/material/blur_background'}
    local function live(w)
        for _,v in pairs(A.worlds() or {}) do if v==w then return true end end
        return false
    end
    function self.clear()
        if gui and live(world) then
            for _,v in ipairs(ids) do pcall(G['destroy_'..v.type],gui,v.id) end
        end
        ids={}
    end
    function self.release()
        if gui and live(world) then self.clear();W.destroy_gui(world,gui) end
        gui,world,ids=nil,nil,{};blur=nil;probe_frames=0
    end
    local function ensure()
        if gui and not live(world) then gui,world,ids=nil,nil,{};blur=nil;probe_frames=0 end
        if not gui then
            local main=A.main_world()
            for _,v in pairs(A.worlds() or {}) do if v~=main then world=v;break end end
            world=world or main;if not world then return end
            gui=W.create_screen_gui(world,'scale',1,1)
        end
        return gui~=nil
    end
    function self.draw(commands)
        if not ensure() then return end
        self.clear()
        if not blur and probe_frames%120==0 and type(A.can_get)=='function' and type(G.bitmap)=='function' then
            for _,name in ipairs(candidates) do
                local ok,available=pcall(A.can_get,'material',name)
                if ok and available then blur=name;break end
            end
        end
        probe_frames=probe_frames+1
        for _,c in ipairs(commands) do
            local color=sr.Color(math.floor(c.a*255+0.5),c.c[1],c.c[2],c.c[3])
            local id
            local kind=c.type
            if c.type=='panel' then
                local drawn=false
                if c.frosted and blur then
                    local ok,bid=pcall(G.bitmap,gui,blur,sr.Vector3(c.x,c.y,48),sr.Vector2(c.w,c.h),sr.Color(math.floor((c.frost_a or c.a)*255+.5),255,255,255))
                    if ok and bid then ids[#ids+1]={type='bitmap',id=bid};drawn=true
                    else blur=nil;probe_frames=1 end
                end
                self.material_status=drawn and ('native frost: '..blur) or 'opaque panel (native frost unavailable or disabled)'
                -- No fake translucent fallback when the game's blur resource is unavailable.
                if not drawn then color=sr.Color(math.floor(c.a*255+.5),c.c[1],c.c[2],c.c[3]) end
                id=G.rect(gui,sr.Vector3(c.x,c.y,49),sr.Vector2(c.w,c.h),color);kind='rect'
            elseif c.type=='rect' then
                id=G.rect(gui,sr.Vector3(c.x,c.y,c.fuel_marker_piece and 51 or 50),sr.Vector2(c.w,c.h),color)
            else
                local resource,material=HUD.native_font.resolve(sr,c.font,false)
                if resource and not c.fuel_endpoint then
                    for _,part in ipairs(HUD.font.numeric_parts(c)) do
                        local ink=part.c or c.c
                        local part_color=sr.Color(math.floor(c.a*part.alpha*255+.5),ink[1],ink[2],ink[3])
                        local tid=G.text(gui,part.text,resource,c.size,material,sr.Vector3(c.x+part.dx,c.y,51),part_color)
                        if tid then ids[#ids+1]={type=kind,id=tid} end
                    end
                end

            end
            if id then ids[#ids+1]={type=kind,id=id} end
        end
    end
    return self
end
return M

end)()
HUD.pose_motion=(function()
-- Frame-rate independent rigid-pose smoothing; no engine userdata retained.
local M={}
local function quaternion(m)
    local a,b,c=m[1],m[6],m[11];local x,y,z,w;local t=a+b+c
    if t>0 then
        local s=math.sqrt(t+1)*2;w=s/4;x=(m[7]-m[10])/s;y=(m[9]-m[3])/s;z=(m[2]-m[5])/s
    elseif a>b and a>c then
        local s=math.sqrt(1+a-b-c)*2;w=(m[7]-m[10])/s;x=s/4;y=(m[5]+m[2])/s;z=(m[9]+m[3])/s
    elseif b>c then
        local s=math.sqrt(1+b-a-c)*2;w=(m[9]-m[3])/s;x=(m[5]+m[2])/s;y=s/4;z=(m[10]+m[7])/s
    else
        local s=math.sqrt(1+c-a-b)*2;w=(m[2]-m[5])/s;x=(m[9]+m[3])/s;y=(m[10]+m[7])/s;z=s/4
    end
    local n=math.sqrt(x*x+y*y+z*z+w*w);return {x/n,y/n,z/n,w/n}
end
local function blend(a,b,t)
    local dot=0;for i=1,4 do dot=dot+a[i]*b[i]end
    local sign=dot<0 and -1 or 1;dot=math.min(1,math.abs(dot))
    local u,v=1-t,t
    if dot<.9995 then local angle=math.acos(dot);local den=math.sin(angle);u=math.sin((1-t)*angle)/den;v=math.sin(t*angle)/den end
    local q={};local n=0;for i=1,4 do q[i]=a[i]*u+b[i]*sign*v;n=n+q[i]^2 end
    n=math.sqrt(n);for i=1,4 do q[i]=q[i]/n end;return q
end
-- Preserve forward direction while aligning the panel's up axis with world up.
function M.upright(m)
    local fx,fy,fz=m[5],m[6],m[7]
    local n=math.sqrt(fx*fx+fy*fy)
    if n<.05 then return m end -- Near vertical aim has no stable horizontal right.
    local rx,ry=fy/n,-fx/n
    return {rx,ry,0,0,fx,fy,fz,0,ry*fz,-rx*fz,rx*fy-ry*fx,0,m[13],m[14],m[15],1}
end
-- Pitch the panel's top toward the weapon's forward axis.
function M.forward_tilt(m,angle)
    local result={};for i=1,16 do result[i]=m[i] end
    local cosine,sine=math.cos(angle),math.sin(angle)
    for i=0,2 do
        result[5+i]=m[5+i]*cosine-m[9+i]*sine
        result[9+i]=m[5+i]*sine+m[9+i]*cosine
    end
    return result
end
function M.step(s,m,x,y,z,key,dt,c)
    dt=type(dt)=='number' and dt==dt and dt>=0 and dt or 1/60
    local q=quaternion(m)
    local jump=s.x and (s.x-x)^2+(s.y-y)^2+(s.z-z)^2>4
    if not s.q or s.key~=key or dt>.35 or jump then
        s.x,s.y,s.z,s.q=x,y,z,q
    else
        local a=c.world_position_smooth==0 and 1 or 1-math.exp(-dt/c.world_position_smooth)
        s.x,s.y,s.z=s.x+(x-s.x)*a,s.y+(y-s.y)*a,s.z+(z-s.z)*a
        local dx,dy,dz=s.x-x,s.y-y,s.z-z;local d=math.sqrt(dx*dx+dy*dy+dz*dz)
        if d>c.world_max_lag then local k=c.world_max_lag/d;s.x,s.y,s.z=x+dx*k,y+dy*k,z+dz*k end
        local t=c.world_rotation_smooth==0 and 1 or 1-math.exp(-dt/c.world_rotation_smooth)
        s.q=blend(s.q,q,t)
    end
    s.key=key
    local a,b,c,d=s.q[1],s.q[2],s.q[3],s.q[4]
    return {1-2*(b*b+c*c),2*(a*b+c*d),2*(a*c-b*d),0,
        2*(a*b-c*d),1-2*(a*a+c*c),2*(b*c+a*d),0,
        2*(a*c+b*d),2*(b*c-a*d),1-2*(a*a+b*b),0,s.x,s.y,s.z,1}
end
return M

end)()
HUD.world_probe=(function()
-- Minimal world-space GUI experiment; only engine-returned world/GUI handles.
local M={}
function M.new(sr,log,direct)
    local A,W,G=sr.Application,sr.World,sr.Gui
    local folded;local smooth={};local depth_fill;local blur;local gui,world;local failed=false;local first=true
    local self={status='not started'}
    local function identity(handle)
        -- LuaJIT %p bypasses the engine's generic '[Material]' __tostring.
        -- This identifies Lua userdata storage, not necessarily its native object.
        local ok,address=pcall(string.format,'%p',handle)
        local native_ok,native=pcall(function()return string.format('0x%X',tonumber(require('ffi').cast('uintptr_t',handle)))end)
        return tostring(handle)..(ok and (' lua_address='..address) or '')..(native_ok and (' native_address='..native) or '')
    end
    local function live(w)
        if not w then return false end
        for _,v in pairs(A.worlds() or {})do if v==w then return true end end
        return false
    end
    function self.release()
        if folded then folded.release();folded=nil end
        if gui and live(world) then
            log('WORLD_GUI destroy begin');W.destroy_gui(world,gui);log('WORLD_GUI destroy complete')
        end
        gui,world=nil,nil;blur=nil;depth_fill=nil;smooth={}
    end
    local function draw(p,c,commands,dt)
        if (not c.world_probe and not commands) or not p then self.release();return end
        if not W.create_world_gui or not G.move or not sr.Matrix4x4 or not sr.Matrix4x4.from_axes then
            self.status='world GUI functions missing';return
        end
        if gui and not live(world) then gui,world=nil,nil;smooth={} end
        local main=A.main_world()
        if not live(main) then self.status='no live main world';return end
        if gui and main~=world then self.release() end
        local fold_commands
        if folded then folded.release();folded=nil end
        local m=p.matrix
        local x,y,z=HUD.scene_test.mount(p,c)
        local px=p.x+m[1]*x+m[5]*y+m[9]*z
        local py=p.y+m[2]*x+m[6]*y+m[10]*z
        local pz=p.z+m[3]*x+m[7]*y+m[11]*z
        if p.gui_pose then px,py,pz=p.x,p.y,p.z end
        if c.keep_hud_upright and not p.gui_pose then m=HUD.pose_motion.upright(m) end
        m=HUD.pose_motion.step(smooth,m,px,py,pz,tostring(c.placement_mode)..':'..tostring(p.id)..':'..tostring(p.candidate),dt,c)
        px,py,pz=m[13],m[14],m[15]
        if first then log('WORLD_GUI matrix begin') end
        local pose=sr.Matrix4x4.from_axes(sr.Vector3(m[1],m[2],m[3]),
            sr.Vector3(m[5],m[6],m[7]),sr.Vector3(m[9],m[10],m[11]),sr.Vector3(px,py,pz))
        if not gui then
            world=main;log('WORLD_GUI create begin')
            gui=assert(W.create_world_gui(world,pose,1000,1000,'immediate'),'world GUI returned nil')
            log('WORLD_GUI create complete')
            local name='mods/dbf_hud/materials/depth_fill'
            local control='mods/dbf_hud/materials/depth_state_test_loader_control'
            if not direct and A.can_get and A.can_get('material',control) then depth_fill=control
            elseif not direct and A.can_get and A.can_get('material',name) then depth_fill=name
            elseif not direct and A.can_get and A.can_get('material','mods/astra_ammo/materials/depth_fill') then
                depth_fill='mods/astra_ammo/materials/depth_fill' -- Previously deployed optional material.
            end
            log('WORLD_GUI depth material '..(direct and 'not requested' or (depth_fill and 'available' or 'missing; install depth material addon')))
            -- One-time observation only: resolve the same material used by bitmap.
            -- Keep no native material handles across frames or GUI destruction.
            if c.debug_logging then
            log('WORLD_GUI instance '..identity(gui)..' world '..identity(world))
            if type(G.material)=='function' and A.can_get then
                for _,material_name in ipairs({'content/ui/shared/material/gui_fill',
                    depth_fill or 'mods/dbf_hud/materials/depth_fill','mods/dbf_hud/materials/depth_blur'}) do
                    if A.can_get('material',material_name) then
                        local ok,handle=pcall(G.material,gui,material_name)
                        log('WORLD_GUI material instance '..material_name..' '..(ok and identity(handle) or 'lookup failed'))
                    end
                end
            else log('WORLD_GUI material inspection unavailable') end
            end
        else
            if first then log('WORLD_GUI move begin') end
            G.move(gui,pose)
        end
        if commands then
            -- Native screen frost renders white on the verified world-GUI path.
            -- Keep the user's frost preference for screen modes; omit it here.
            -- Bitmap takes the material as a required argument. This avoids relying
            -- on the game's optional rect material overload matching upstream.
            local function solid(x,y,w,h,layer,color)
                if depth_fill then
                    G.bitmap(gui,depth_fill,sr.Vector3(x,y,layer),sr.Vector2(w,h),color)
                else G.rect(gui,sr.Vector3(x,y,layer),sr.Vector2(w,h),color) end
            end
            for _,v in ipairs(commands) do
                local color=sr.Color(math.floor(v.a*255+.5),v.c[1],v.c[2],v.c[3])
                if v.type=='panel' then
                    -- Match the known-working hybrid background; leave experimental
                    -- depth fill on foreground primitives only during this comparison.
                    solid(v.x,v.y,v.w,v.h,1,color)
                elseif v.type=='rect' then
                    solid(v.x,v.y,v.w,v.h,v.scanline_layer and 2.5 or (v.fuel_marker_piece and 3 or 2),color)
                else
                    local resource,material=HUD.native_font.resolve(sr,v.font,c.occlusion_mode~='gui')
                    if resource and not v.fuel_endpoint then
                        for _,part in ipairs(HUD.font.numeric_parts(v)) do
                            local ink=part.c or v.c
                        local part_color=sr.Color(math.floor(v.a*part.alpha*255+.5),ink[1],ink[2],ink[3])
                            G.text(gui,part.text,resource,v.size,material,sr.Vector3(v.x+part.dx,v.y,3),part_color)
                        end
                    end

                end
            end
            if fold_commands and #fold_commands>0 then
                folded=folded or M.new(sr,log,direct)
                local child_panel=fold_commands[1];local edge=child_panel.y+child_panel.h
                local child={}
                for _,v in ipairs(fold_commands) do
                    local copy={};for k,value in pairs(v) do copy[k]=value end
                    copy.y=v.y-edge
                    if copy.type=='text' then
                        local a,b,e,f=HUD.font.measure(copy.text,copy.size,copy.font,true)
                        copy.x=child_panel.x+child_panel.w/2-(a+e)/2
                        copy.y=-child_panel.h/2-(b+f)/2
                    end
                    child[#child+1]=copy
                end
                local hinge=commands[1].y-2
                local upright=HUD.pose_motion.forward_tilt(m,-math.pi/2)
                local child_pose={matrix=upright,x=px+m[9]*hinge/1000,y=py+m[10]*hinge/1000,z=pz+m[11]*hinge/1000,id=p.id,candidate='folded reserve',gui_pose=true}
                folded.draw(child_pose,c,child,dt)
            end
            if first then log('WORLD_GUI panel submitted: '..(depth_fill and 'explicit material bitmap path' or 'default rectangle path'));first=false end
            self.status='world panel; frost unavailable on this rendering path';return true
        end
        if first then log('WORLD_GUI rect begin') end
        G.rect(gui,sr.Vector3(0,0,0),sr.Vector2(240,140),sr.Color(255,45,52,55))
        G.rect(gui,sr.Vector3(0,0,1),sr.Vector2(12,140),sr.Color(255,231,200,92))
        if first then log('WORLD_GUI rect complete');first=false end
        self.status='world rectangle submitted'
    end
    function self.draw(p,c,commands,dt)
        if failed then return end
        local ok,err=pcall(draw,p,c,commands,dt)
        if not ok then
            failed=true;self.status=tostring(err);log('WORLD_GUI Lua failure: '..self.status)
            pcall(self.release)
        end
        return ok and err==true
    end
    return self
end
return M

end)()
HUD.depth_marker=(function()
-- Isolated per-primitive depth marker. No Gui.move, profile edits or shared material writes.
local M={}
function M.new(sr,log)
    local gui,world,failed,access_reported,compare_reported;local ids={};local self={status='not started'}
    local material='mods/dbf_hud/materials/depth_state_test_loader_control'
    local access_material='mods/dbf_hud/materials/screen_scene_depth_access'
    local compare_material='mods/dbf_hud/materials/screen_scene_depth_compare'
    local function live(w)
        for _,v in pairs(sr.Application.worlds() or {}) do if v==w then return true end end
        return false
    end
    function self.release()
        if gui and live(world) then sr.World.destroy_gui(world,gui) end
        gui,world=nil,nil;ids={}
    end
    function self.draw(position,camera,fov,height,width)
        if failed then return false end
        if not position or not camera then self.release();return false end
        local ok,err=pcall(function()
            assert(type(sr.Gui.bitmap_3d)=='function','bitmap_3d unavailable')
            assert(sr.Application.can_get('material',material),'depth marker material unavailable')
            local main=sr.Application.main_world()
            local target=main
            if width then
                for _,candidate in pairs(sr.Application.worlds() or {}) do
                    if candidate~=main then target=candidate;break end
                end
            end
            if world~=target or not live(world) then self.release() end
            assert(live(target),'no GUI world')
            if not gui then
                world=target
                if width then gui=assert(sr.World.create_screen_gui(world,'scale',1,1))
                else gui=assert(sr.World.create_world_gui(world,sr.Matrix4x4.identity(),1,1,'immediate')) end
            end
            if width then
                for _,id in ipairs(ids) do sr.Gui.destroy_bitmap(gui,id) end
                ids={}
                local point=HUD.projection.project(camera,position.x,position.y,position.z,fov,width/height,.05)
                if not point then return end
                local radius,stroke=14*height/1080,1.5*height/1080
                local comparing=sr.Application.can_get('material',compare_material)
                local encoded=math.floor(math.max(0,math.min(64,point.depth))*65535/64+.5)
                local color=comparing and sr.Color(255,encoded%256,math.floor(encoded/256),0) or sr.Color(255,0,255,0)
                for _,edge in ipairs({{-radius,-radius,2*radius,stroke},{-radius,radius-stroke,2*radius,stroke},
                    {-radius,-radius,stroke,2*radius},{radius-stroke,-radius,stroke,2*radius}}) do
                    local id=sr.Gui.bitmap(gui,comparing and compare_material or material,sr.Vector3(point.x*width+edge[1],point.y*height+edge[2],50),
                        sr.Vector2(edge[3],edge[4]),color)
                    if id then ids[#ids+1]=id end
                end
                if comparing and not compare_reported then
                    compare_reported=true;log('SCENE_DEPTH comparison material loaded; green outline submitted; depth units provisional')
                end
                if not comparing and sr.Application.can_get('material',access_material) then
                    local side=128*height/1080
                    local id=sr.Gui.bitmap(gui,access_material,sr.Vector3(point.x*width+24*height/1080,
                        point.y*height-side*.5,50),sr.Vector2(side,side),sr.Color(255,255,255,255))
                    if id then ids[#ids+1]=id end
                    if not access_reported then
                        access_reported=true;log('SCENE_DEPTH access material loaded; screen tile submitted; texture contents unverified')
                    end
                end
                self.status='screen depth material submitted';return
            end
            local v=sr.Vector3
            local tm=sr.Matrix4x4.from_axes(v(camera[1],camera[2],camera[3]),
                v(camera[5],camera[6],camera[7]),v(camera[9],camera[10],camera[11]),
                v(position.x,position.y,position.z))
            local depth=(position.x-camera[13])*camera[5]+(position.y-camera[14])*camera[6]+(position.z-camera[15])*camera[7]
            if depth<=0 then return end
            local unit=2*depth*math.tan(fov*.5)/height
            local radius,stroke=10*height/1080*unit,1.5*height/1080*unit
            local color=sr.Color(255,255,0,255)
            for _,edge in ipairs({{-radius,-radius,2*radius,stroke},{-radius,radius-stroke,2*radius,stroke},
                {-radius,-radius,stroke,2*radius},{radius-stroke,-radius,stroke,2*radius}}) do
                sr.Gui.bitmap_3d(gui,material,tm,v(edge[1],edge[2],0),2,sr.Vector2(edge[3],edge[4]),color)
            end
            self.status='depth marker submitted'
        end)
        if not ok then failed=true;self.status=tostring(err);log('DEPTH_MARKER failure '..self.status);pcall(self.release) end
        return ok and (self.status=='depth marker submitted' or self.status=='screen depth material submitted')
    end
    return self
end
return M

end)()
HUD.offscreen_test=(function()
-- Isolated one-frame render test. Never renders from the update callback.
local M={}
function M.start(sr,log,globals,panel_provider,show_preview)
    globals=globals or _G
    local self={};local active=true;local submitted=false;local first_render=true
    local A,W,R,V,U,G=sr.Application,sr.World,sr.Renderer,sr.Viewport,sr.Unit,sr.Gui
    local world,viewport,target,camera,environment,gui
    local preview,preview_world
    local world_ready=false
    local source_ids={};local elapsed=0
    local texture_w,texture_h=64,64
    local density=panel_provider and 4 or 1
    function self.tick(dt,refresh_hz,scanline_strength)
        elapsed=elapsed+(dt or 0)
        if panel_provider and active and world and gui and (not world_ready or refresh_hz==0 or elapsed>=1/(refresh_hz or 60)) then
            elapsed=0
            local commands=panel_provider()
            if commands then
                local f=commands[1]
                assert(f.w>0 and f.h>0,'invalid panel bounds')
                if math.ceil(f.w*density)~=texture_w or math.ceil(f.h*density)~=texture_h then
                    self.resize_required=true;return
                end
                self.aspect=texture_w/texture_h
                local sx,sy=density,density
                for _,id in ipairs(source_ids) do G.destroy_rect(gui,id) end
                source_ids={}
                local function rect(x,y,w,h,c,a)
                    -- Preserve the selected RGB values; no experimental color transform.
                    local rgb=c
                    local function strip(bottom,height,factor)
                        local id=G.rect(gui,sr.Vector3((x-f.x)*sx,(bottom-f.y)*sy,1),sr.Vector2(w*sx,height*sy),sr.Color(math.floor(255*(a or 1)),math.floor(rgb[1]*factor+0.5),math.floor(rgb[2]*factor+0.5),math.floor(rgb[3]*factor+0.5)))
                        source_ids[#source_ids+1]=id
                    end
                    local strength=scanline_strength or 0
                    if strength<=0 then strip(y,h,1);return end
                    -- One dim row per four source pixels, aligned across all primitives.
                    -- Modulate RGB only: never paint opaque bands into clear texels.
                    local bottom=y
                    while bottom<y+h do
                        local row=math.floor(bottom-f.y+0.000001)
                        local top=math.min(y+h,f.y+row+1)
                        if top<=bottom then break end
                        strip(bottom,top-bottom,row%4==0 and (1-strength) or 1)
                        bottom=top
                    end
                end
                for _,c in ipairs(commands) do
                    if c.type=='text' then
                        -- Archived mesh glyph rendering removed.
                    else rect(c.x,c.y,c.w,c.h,c.c,c.a) end
                end
                world_ready=false;submitted=false
            end
        end
        if active and world and not world_ready then
            world_ready=true
            if type(W.update)=='function' then
                if not panel_provider then log('OFFSCREEN private world update begin') end
                local ok,err=pcall(W.update,world,0)
                if not panel_provider or not ok then log(ok and 'OFFSCREEN private world update complete' or ('OFFSCREEN private world update failed '..tostring(err))) end
                if not ok then active=false end
            else log('OFFSCREEN private world update unavailable') end
        end
    end
    local bridge=rawget(globals,'HUDRenderBridge');local unsubscribe
    function self.release()
        active=false
        if unsubscribe then unsubscribe();unsubscribe=nil end
        local ok=true
        local function destroy(fn,...)
            if not ok then return end
            local done,err=pcall(fn,...);ok=done
            if not done then log('OFFSCREEN cleanup failed '..tostring(err)) end
        end
        if preview then
            local live=false
            for _,w in pairs(A.worlds() or {}) do if w==preview_world then live=true end end
            if live then destroy(W.destroy_gui,preview_world,preview) end
            if ok then preview=nil end
        end
        if gui then destroy(W.destroy_gui,world,gui);if ok then gui=nil end end
        if viewport then destroy(A.destroy_viewport,world,viewport);if ok then viewport=nil end end
        if environment then destroy(W.destroy_shading_environment,world,environment);if ok then environment=nil end end
        if world then destroy(A.release_world,world);if ok then world=nil end end
        if target then destroy(R.destroy_resource,target);if ok then target=nil end end
        if ok then log('OFFSCREEN cleanup complete') end
    end
    if not bridge or bridge.api~=1 or type(bridge.subscribe)~='function' then
        local loader=rawget(globals,'CowboyBingusModLoader')
        local state=loader and loader.modules and loader.modules['mods/holographic_utility_display/render_bridge']
        log('OFFSCREEN blocked: startup HUD render bridge required; loader='..tostring(state)..'; render='..type(rawget(globals,'render')))
        self.waiting_for_bridge=true
        return self
    end
    if panel_provider then
        local commands=panel_provider()
        if not commands then self.waiting_for_panel=true;return self end
        texture_w,texture_h=math.ceil(commands[1].w*density),math.ceil(commands[1].h*density)
        assert(texture_w>0 and texture_h>0 and texture_w<=2048 and texture_h<=2048,'panel texture bounds invalid')
        self.aspect=texture_w/texture_h
    end
    local ok,err=pcall(function()
        for _,pair in ipairs({{A,'new_world'},{A,'release_world'},{A,'create_viewport'},{A,'destroy_viewport'},
            {A,'render_world'},{A,'can_get'},{W,'spawn_unit'},{W,'create_screen_gui'},
            {W,'destroy_gui'},{W,'destroy_shading_environment'},
            {U,'camera'},{R,'create_resource'},{R,'destroy_resource'},{V,'set_output_render_target'},
            {G,'rect'}}) do assert(pair[1] and type(pair[1][pair[2]])=='function','missing '..pair[2]) end
        local name='core/units/camera'
        if not A.can_get('unit',name) then name='core/appkit/units/camera/camera' end
        if not A.can_get('unit',name) then
            for _,ns_name in ipairs({'Camera','World','Application'}) do
                local names={};local ns=sr[ns_name]
                if type(ns)=='table' then for key,value in pairs(ns) do
                    if type(key)=='string' and type(value)=='function' and
                        (ns_name=='Camera' or key:lower():find('camera',1,true)) then names[#names+1]=key end
                end end
                table.sort(names);log('OFFSCREEN CAMERA_API '..ns_name..' '..table.concat(names,' '))
            end
            for _,candidate in ipairs({'core/appkit/units/camera','content/markers/camera_marker',
                'core/editor_slave/stingray_editor/editor_camera'}) do
                log('OFFSCREEN CAMERA_RESOURCE '..candidate..' '..tostring(A.can_get('unit',candidate)))
            end
        end
        assert(A.can_get('unit',name),'camera resource unavailable: '..name)
        local environment_name='core/stingray_renderer/environments/midday/midday'
        local default_environment=type(W.create_default_shading_environment)=='function'
        if not default_environment then
            assert(type(W.create_shading_environment)=='function','missing create_shading_environment')
            assert(A.can_get('shading_environment',environment_name),'default environment resource unavailable')
        end
        log('OFFSCREEN setup begin')
        world=assert(A.new_world())
        local unit=assert(W.spawn_unit(world,name))
        camera=assert(U.camera(unit,1),'camera unavailable')
        environment=assert(default_environment and W.create_default_shading_environment(world)
            or W.create_shading_environment(world,environment_name))
        viewport=assert(A.create_viewport(world,'offscreen_ui_weapon_screen'))
        target=assert(R.create_resource('render_target','R8G8B8A8',texture_w,texture_h))
        V.set_output_render_target(viewport,target)
        self.texture=target
        gui=assert(W.create_screen_gui(world,'scale',1,1))
        if not panel_provider then
        for i,color in ipairs({{230,60,60},{60,210,100},{60,110,230},{230,200,60}}) do
            G.rect(gui,sr.Vector3(((i-1)%2)*32,math.floor((i-1)/2)*32,1),sr.Vector2(32,32),
                sr.Color(255,color[1],color[2],color[3]))
        end
        end
        log(string.format('OFFSCREEN source GUI ready at %dx%d',texture_w,texture_h))
    end)
    if not ok then log('OFFSCREEN setup stopped '..tostring(err));self.release();return self end
    unsubscribe=bridge.subscribe('dbf_hud.offscreen',function(...)
        if active and world_ready and not submitted then
            submitted=true
            if first_render then log('OFFSCREEN render callback entered') end
            local done,why=pcall(A.render_world,world,camera,viewport,environment)
            if first_render or not done then log(done and 'OFFSCREEN render submitted; pixels unverified' or ('OFFSCREEN render failed '..tostring(why))) end
            first_render=false
            if done and show_preview~=false and not preview then
                local shown,reason=pcall(function()
                    log('OFFSCREEN preview preflight begin')
                    assert(type(G.material)=='function','Gui.material unavailable')
                    assert(sr.Material and type(sr.Material.set_resource)=='function','Material.set_resource unavailable')
                    assert(type(G.bitmap)=='function','Gui.bitmap unavailable')
                    assert(type(A.main_world)=='function','Application.main_world unavailable')
                    assert(A.can_get('material','content/ui/shared/material/gui_diffuse_map'),'preview material unavailable')
                    local main=assert(A.main_world())
                    preview_world=main
                    for _,candidate in pairs(A.worlds() or {}) do
                        if candidate~=main and candidate~=world then preview_world=candidate;break end
                    end
                    log('OFFSCREEN preview world '..(preview_world==main and 'main fallback' or 'HUD world'))
                    log('OFFSCREEN preview GUI create begin')
                    preview=assert(W.create_screen_gui(preview_world,'scale',1,1))
                    -- Independent control: visible geometry does not depend on the render target.
                    G.rect(preview,sr.Vector3(896,296,79),sr.Vector2(panel_provider and texture_w/density+8 or 200,panel_provider and texture_h/density+8 or 200),sr.Color(255,255,0,255))
                    G.rect(preview,sr.Vector3(panel_provider and 916+texture_w/density or 1104,300,80),sr.Vector2(48,48),sr.Color(255,255,255,255))
                    for i,color in ipairs({{255,0,0},{255,255,0},{0,255,0},{0,0,255},{128,128,128},{255,255,255}}) do
                        G.rect(preview,sr.Vector3(900+(i-1)*32,260,81),sr.Vector2(32,24),sr.Color(255,color[1],color[2],color[3]))
                    end
                    log('OFFSCREEN color comparison reference enabled')
                    log('OFFSCREEN preview material lookup begin')
                    for _,candidate in ipairs({'core/performance_hud/gui','content/ui/shared/material/gui_diffuse_map','content/ui/shared/material/gui_fill','content/ui/shared/material/gui_white_alpha'}) do
                        if A.can_get('material',candidate) then
                            local valid,result=pcall(function()
                                local ffi=require('ffi')
                                return string.format('0x%X',tonumber(ffi.cast('uintptr_t',G.material(preview,candidate))))
                            end)
                            log('OFFSCREEN material candidate '..candidate..' '..(valid and result or 'lookup failed'))
                        else log('OFFSCREEN material candidate '..candidate..' unavailable') end
                    end
                    local material=assert(G.material(preview,'content/ui/shared/material/gui_diffuse_map'))
                    log('OFFSCREEN material Lua type='..type(material)..'; target Lua type='..type(target))
                    local pointer_ok,pointers=pcall(function()
                        local ffi=require('ffi')
                        local mp=tonumber(ffi.cast('uintptr_t',material))
                        local tp=tonumber(ffi.cast('uintptr_t',target))
                        assert(mp and mp>=65536,'Gui.material returned a null or invalid native pointer')
                        assert(tp and tp>=65536,'render target returned a null or invalid native pointer')
                        return string.format('material=0x%X target=0x%X',mp,tp)
                    end)
                    assert(pointer_ok,pointers)
                    log('OFFSCREEN native pointer check '..pointers)
                    -- Native signature and diffuse_map slot verified; null handles rejected above.
                    log('OFFSCREEN verified texture binding begin')
                    sr.Material.set_resource(material,'diffuse_map',target)
                    log('OFFSCREEN preview bitmap draw begin')
                    G.bitmap(preview,'content/ui/shared/material/gui_diffuse_map',sr.Vector3(900,300,80),sr.Vector2(panel_provider and texture_w/density or 192,panel_provider and texture_h/density or 192),sr.Color(255,255,255,255))
                    log('OFFSCREEN four-color preview placed above/right of native bottom-left HUD')
                end)
                if not shown then log('OFFSCREEN preview stopped '..tostring(reason)) end
            end
        end
    end)
    log('OFFSCREEN waiting for render callback')
    return self
end
return M

end)()
HUD.world_style=(function()
-- Pure WorldGUI geometry scaling, frame fitting and visual presets.
local M={}
function M.prepare(commands,p,c)
                    local f=commands[1];local scale=240*(c.scale or 1)/(f.world_reference_width or f.w)
                    if f.double_breech then scale=scale*(f.breech_scale or 1) end
                    if c.placement_mode=='auto' and p.first_person then scale=scale*.5 end;local centered={}
                    for _,command in ipairs(commands) do
                        local v={};for k,value in pairs(command) do v[k]=value end
                        if command.type=='panel' then v.source_panel=command end
                        if v.effect_band then v.effect_band=v.effect_band*scale end
                        v.x=(v.x-f.x-f.w/2)*scale;v.y=(v.y-f.y-f.h/2)*scale
                        if v.texture_art_box then local b=v.texture_art_box;v.texture_art_box={x=(b.x-f.x-f.w/2)*scale,y=(b.y-f.y-f.h/2)*scale,w=b.w*scale,h=b.h*scale} end
                        if v.readout_zone then local z=v.readout_zone;v.readout_zone={cx=(z.cx-f.x-f.w/2)*scale,cy=(z.cy-f.y-f.h/2)*scale,w=z.w*scale,h=z.h*scale} end
                        if v.quad then local q={};for i,p in ipairs(v.quad) do q[i]={(p[1]-f.x-f.w/2)*scale,(p[2]-f.y-f.h/2)*scale} end;v.quad=q end
                        if v.w then v.w=v.w*scale end
                        if v.h then v.h=v.h*scale end
                        if v.size then v.size=v.size*scale end
                        centered[#centered+1]=v
                    end
                    if f.neo_panel then return centered end
                    -- Pixel glyphs quantize after world scaling; fit their actual bounds.
                    if HUD.font.supported(c.font) then
                        local panel=centered[1]
                        local left,bottom,right,top=panel.x,panel.y,panel.x+panel.w,panel.y+panel.h
                        local padding=math.max(1,8*2*(c.scale or 1)*scale)
                        for _,v in ipairs(centered) do
                            if v.type=='text' and not v.child and not v.texture_readout then
                                local a,b,e,f=HUD.font.measure(v.text,v.size,v.font,true)
                                left=math.min(left,v.x+a-padding);bottom=math.min(bottom,v.y+b-padding)
                                right=math.max(right,v.x+e+padding);top=math.max(top,v.y+f+padding)
                            end
                        end
                        for _,v in ipairs(centered) do
                            if v.decoration and not v.child and not v.charge_meter then
                                v.x=left+(v.x-panel.x)*(right-left)/panel.w
                                v.y=bottom+(v.y-panel.y)*(top-bottom)/panel.h
                                v.w=v.w*(right-left)/panel.w
                                v.h=v.h*(top-bottom)/panel.h
                            end
                        end
                        panel.x,panel.y,panel.w,panel.h=left,bottom,right-left,top-bottom
                    end
                    -- World glyph scaling and frame fitting may change the final
                    -- bounds after screen-layout centering. Align actual glyphs here.
                    local panel=centered[1];local middle=panel.x+panel.w/2
                    local bar_left,bar_right=math.huge,-math.huge
                    for _,v in ipairs(centered) do
                        if v.heat_label then
                            local a,b,e,f=HUD.font.measure(v.text,v.size,v.font,true)
                            if not e then a,e=0,#v.text*v.size*.6 end
                            local pad=8*2*(c.scale or 1)*scale
                            if v.heat_label=='percent' then
                                local pa,pb,pe=HUD.font.measure(v.heat_prefix,v.size,v.font,true)
                                local slot_width=0
                                for digit=0,9 do local da,db,de=HUD.font.measure(tostring(digit),v.size,v.font,true);slot_width=math.max(slot_width,(de or v.size*.6)-(da or 0)) end
                                v.x=panel.x+pad+(pe or #v.heat_prefix*v.size*.6)+(v.heat_digit_slot or 0)*slot_width
                            else v.x=v.heat_label=='left' and panel.x+pad-a or panel.x+panel.w-pad-e end
                        elseif v.center_in_frame then
                            local a,b,e,f
                            if HUD.font.supported(v.font) then a,b,e,f=HUD.font.measure(v.text,v.size,v.font,true) end
                            if not e then a,e=0,#v.text*v.size*.6 end
                            v.x=middle-(a+e)/2
                        elseif v.center_bar then
                            bar_left=math.min(bar_left,v.x);bar_right=math.max(bar_right,v.x+v.w)
                        end
                    end
                    if bar_left<math.huge then
                        local shift=middle-(bar_left+bar_right)/2
                        for _,v in ipairs(centered) do if v.center_bar then v.x=v.x+shift end end
                    end
                    local heading;local icon_left,icon_right=math.huge,-math.huge
                    for _,v in ipairs(centered) do
                        if v.mode_count then heading=v end
                        if v.mode_icon then icon_left=math.min(icon_left,v.x);icon_right=math.max(icon_right,v.x+v.w) end
                    end
                    if heading and icon_left<math.huge then
                        local a,b,e,f
                        if HUD.font.supported(heading.font) then a,b,e,f=HUD.font.measure(heading.text,heading.size,heading.font,true) end
                        if not e then a,e=0,#heading.text*heading.size*.6 end
                        local gap=(heading.mode_gap or 8)*scale;local width=e-a+gap+icon_right-icon_left
                        local start=middle-width/2;heading.x=start-a
                        local shift=start+e-a+gap-icon_left
                        for _,v in ipairs(centered) do if v.mode_icon then v.x=v.x+shift end end
                    end
                    local fuel_left,fuel_right=math.huge,-math.huge
                    for _,v in ipairs(centered) do
                        if v.fuel_group then
                            local a,e=0,v.w or 0
                            if v.type=='text' then
                                local b,f
                                a,b,e,f=HUD.font.measure(v.text,v.size,v.font,true)
                                if not e then a,e=0,#v.text*v.size*.6 end
                            end
                            fuel_left=math.min(fuel_left,v.x+a);fuel_right=math.max(fuel_right,v.x+e)
                        end
                    end
                    if fuel_left<math.huge then
                        local shift=middle-(fuel_left+fuel_right)/2
                        for _,v in ipairs(centered) do if v.fuel_group then v.x=v.x+shift end end
                    end
                    local child_panel,child_text
                    for _,v in ipairs(centered) do
                        if v.child and not v.heat_child and v.type=='panel' then child_panel=v end
                        if v.child and not v.heat_child and v.type=='text' then child_text=v end
                    end
                    if child_panel and child_text then
                        local old={x=child_panel.x,y=child_panel.y,w=child_panel.w,h=child_panel.h}
                        local a,b,e,f
                        if HUD.font.supported(child_text.font) then a,b,e,f=HUD.font.measure(child_text.text,child_text.size,child_text.font,true) end
                        if not e then a,b,e,f=0,-child_text.size*.2,#child_text.text*child_text.size*.6,child_text.size*.8 end
                        local pad=4*2*(c.scale or 1)*scale
                        local width,height=panel.w,f-b+2*pad
                        child_panel.x=middle-width/2;child_panel.y=panel.y-2*2*(c.scale or 1)*scale-height
                        child_panel.w,child_panel.h=width,height
                        child_text.x=middle-(a+e)/2;child_text.y=child_panel.y+pad-b
                        for _,v in ipairs(centered) do
                            if v.child and not v.heat_child and v.decoration then
                                v.x=child_panel.x+(v.x-old.x)*width/old.w
                                v.y=child_panel.y+(v.y-old.y)*height/old.h
                                v.w=v.w*width/old.w;v.h=v.h*height/old.h
                            end
                        end
                    end
                    -- The charge instrument spans the final font-fitted window, including mode footer.
                    local meter
                    for _,v in ipairs(centered) do if v.charge_meter and v.type=='panel' then meter=v end end
                    if meter then
                        local old_y,old_h,old_x=meter.y,meter.h,meter.x
                        local low=child_panel and math.min(panel.y,child_panel.y) or panel.y
                        local height=panel.y+panel.h-low
                        local new_x=panel.x+panel.w+2*2*(c.scale or 1)*scale
                        for _,v in ipairs(centered) do if v.charge_meter then
                            v.y=low+(v.y-old_y)*height/old_h
                            v.h=v.h*height/old_h
                            v.x=v.x+new_x-old_x
                        end end
                    end
                    for _,v in ipairs(centered) do
                        if v.heat_overlay then
                            local inset=2*(c.scale or 1)*scale
                            v.x,v.y=panel.x+inset,panel.y+inset
                            v.w=math.max(0,panel.w-2*inset)*v.heat_fraction
                            v.h=math.max(0,panel.h-2*inset)
                        end
                    end
                    -- Equal apparent pitch across the final fitted parent and child.
                    local template;local kept={}
                    for _,v in ipairs(centered)do
                        if v.df_effect_frame and not v.df_effect_sweep then template=template or v
                        else
                            if v.df_effect_frame then
                                local target=v.df_effect_frame=='child' and child_panel or panel
                                if target then v.x=target.x;v.w=target.w;v.y=target.y+(target.h-v.h)*v.df_effect_fraction end
                            end
                            kept[#kept+1]=v
                        end
                    end
                    if template then
                        centered=kept
                        local density=c.effect_scanline_count or 21
                        local pitch=math.max((child_panel and child_panel.h or 44)/(density+1),panel.h/161)
                        for _,target in ipairs({panel,child_panel})do
                            local count=math.min(160,math.max(1,math.floor(target.h/pitch)-1))
                            for k=1,count do
                                centered[#centered+1]={type='rect',x=target.x,y=target.y+k*pitch,w=target.w,h=math.min(template.h,pitch*.4),c=template.c,a=template.a,df_effect_frame=target==child_panel and 'child' or 'main',df_effect_fraction=k*pitch/target.h,scanline_layer=true}
                            end
                        end
                    end
                    if c.style_3d=='hologram' then
                        local panel=centered[1];local clock=c.style_clock or 0
                        local flicker=.96+.025*math.sin(clock*17)+.015*math.sin(clock*31)
                        for _,v in ipairs(centered) do v.a=v.a*flicker end
                        panel.a=panel.a*.18
                        if child_panel then child_panel.a=child_panel.a*.18 end
                        local ink=HUD.config.rgb(c.text_color)
                        local strength=c.visibility_alpha or (commands[2] and commands[2].a) or 1
                        local frames={panel}
                        if child_panel then frames[#frames+1]=child_panel end
                        for _,frame in ipairs(frames) do
                            local thickness=math.max(.3,frame.w/500)
                            for _,edge in ipairs({{frame.x,frame.y,frame.w,thickness},{frame.x,frame.y+frame.h-thickness,frame.w,thickness}}) do
                                centered[#centered+1]={type='rect',x=edge[1],y=edge[2],w=edge[3],h=edge[4],c=ink,a=.18*strength}
                            end
                            centered[#centered+1]={type='rect',x=frame.x,y=frame.y+(clock*.35%1)*(frame.h-thickness),w=frame.w,h=thickness,c=ink,a=.10*strength}
                        end
                    end
    if c.style_3d=='instrument' or c.style_3d=='blueprint' or c.style_3d=='retro' then
        local blueprint,retro=c.style_3d=='blueprint',c.style_3d=='retro'
        local accent=retro and HUD.config.rgb(c.text_color) or blueprint and {92,194,230} or {235,175,70}
        local frames={};for _,v in ipairs(centered) do if v.type=='panel' then frames[#frames+1]=v end end
        for _,frame in ipairs(frames) do
            if not retro and c.background_color=='#202628' then frame.c=blueprint and {12,28,42} or {35,28,17} end
            local t=math.max(.45,frame.w/180)
            local function line(x,y,w,h,alpha)
                centered[#centered+1]={type='rect',x=x,y=y,w=w,h=h,c=accent,a=alpha*(c.visibility_alpha or 1)}
            end
            if retro then
                for k=1,21 do line(frame.x,frame.y+frame.h*k/22,frame.w,t*.5,.14) end
            elseif blueprint then
                for k=1,7 do line(frame.x+frame.w*k/8,frame.y,t*.4,frame.h,.09) end
                for k=1,3 do line(frame.x,frame.y+frame.h*k/4,frame.w,t*.4,.09) end
            end
        end
    end
    HUD.layout.fuel_marker(centered,function(t,size,font)return HUD.font.measure(t,size,font,true)end)
    -- Shared physical spacing and travel rate, measured on the fitted main box.
    local sweep_panels,templates,kept={},{},{}
    for _,v in ipairs(centered)do if v.type=='panel' and v.source_panel then sweep_panels[v.source_panel]=v end end
    -- Scanline materials follow the final fitted box, including resized child footers.
    for _,v in ipairs(centered)do
        if v.effect_shader_band and v.effect_owner then
            local frame=sweep_panels[v.effect_owner]
            if frame then
                v.x=frame.x;v.w=frame.w
                v.y=frame.y+frame.h*math.max(0,math.min(1,v.df_effect_fraction or 0))
                v.h=math.max(0,math.min(v.h,frame.y+frame.h-v.y))
                v.child=frame.child;v.fold_child=frame.fold_child
                v.panel_uv={0,1-(v.y-frame.y+v.h)/math.max(.001,frame.h),1,1-(v.y-frame.y)/math.max(.001,frame.h)}
            end
        end
    end
    for _,v in ipairs(centered)do
        if v.df_effect_sweep and v.effect_owner then templates[v.effect_owner]=templates[v.effect_owner] or v
        else kept[#kept+1]=v end
    end
    local reference=centered[1]
    local spacing=math.max(.001,reference.h/math.max(1,math.min(12,c.effect_sweep_density or 3)))
    local speed=(c.effect_sweep_speed or .35)*reference.h
    for owner,template in pairs(templates)do
        local frame=sweep_panels[owner]
        if frame then
            local band=math.max(0,math.min(template.effect_band or template.h or 0,frame.h))
            local offset=((template.effect_clock or 0)*speed)%spacing
            for k=-1,math.ceil(frame.h/spacing)do
                local low=offset+k*spacing
                local bottom=math.max(0,low);local top=math.min(frame.h,low+band)
                if top>bottom then
                    local v={};for key,value in pairs(template)do v[key]=value end
                    v.x=frame.x;v.w=math.max(0,frame.w);v.y=frame.y+bottom;v.h=top-bottom
                    v.child=frame.child;v.fold_child=frame.fold_child
                    v.panel_uv={0,1-top/math.max(.001,frame.h),1,1-bottom/math.max(.001,frame.h)}
                    kept[#kept+1]=v
                end
            end
        end
    end
    centered=kept
    if HUD.bespoke_texture_panel then
        for _,v in ipairs(centered) do if v.texture_readout then
            HUD.bespoke_texture_panel.fit(v,function(t,size,font)return HUD.font.measure(t,size,font,true) end)
        end end
    end
    return centered
end
return M

end)()
HUD.archived_mesh=(function()
-- Archived mesh carrier. Production uses direct WorldGUI.
local M={}
function M.new(sr,log,side)
    local A,W,U,Mesh=sr.Application,sr.World,sr.Unit,sr.Mesh
    local unit,world,bound,scene_material,last_emission,screen_test;local failed=false;local smooth={}
    local self={}
    local function live(w)
        for _,v in pairs(A.worlds() or {}) do if w==v then return true end end
        return false
    end
    function self.release()
        if unit and live(world) then W.destroy_unit(world,unit) end
        unit,world,bound,scene_material,last_emission=nil,nil,nil,nil,nil;smooth={}
    end
    function self.draw(p,c,target,dt,aspect)
        if failed then return end
        if not p or not target then if unit then self.release() end;return end
        local ok,err=pcall(function()
            local main=A.main_world()
            if not live(main) then return end
            if unit and (world~=main or not live(world)) then self.release() end
            if unit and screen_test~=(c.weapon_screen_test==true) then self.release() end
            if not unit then
                local name='content/art_shared/meshes/plane_primitive'
                assert(A.can_get('unit',name),'plane unit unavailable')
                for _,fn in ipairs({'set_local_pose','set_local_scale','num_meshes','mesh'}) do assert(type(U[fn])=='function','missing Unit.'..fn) end
                assert(Mesh and type(Mesh.num_materials)=='function' and type(Mesh.material)=='function','mesh material API unavailable')
                world=main
                for _,candidate in ipairs({'mods/dbf_hud/materials/fullbright_depth_image','core/appkit/materials/loading_screen','content/effects/base_shaders/mesh_particle_simple','content/env_ship/hangar/props/materials/store_screen_large','content/fac_helldivers/equipment/primary_weapons/assault_rifle_nacho/materials/weapon_screen'}) do
                    log('SCENE fullbright candidate '..candidate..' loaded='..tostring(A.can_get('material',candidate)))
                end
                log('SCENE plane spawn begin')
                unit=assert(W.spawn_unit(world,name))
                assert(U.num_meshes(unit)==1,'unexpected mesh count')
                if type(U.set_mesh_visibility)=='function' then
                    log('SCENE shadow-only visibility begin side='..side)
                    U.set_mesh_visibility(unit,1,false,'shadow_caster')
                    log('SCENE shadow-only visibility returned side='..side)
                end
                local mesh=U.mesh(unit,1)
                assert(Mesh.num_materials(mesh)==1,'unexpected material count')
                local transparent='content/art_shared/materials/placeholder_red_transparent'
                screen_test=c.weapon_screen_test==true
                if screen_test then transparent='content/fac_helldivers/equipment/primary_weapons/assault_rifle_nacho/materials/weapon_screen' end
                local alpha=type(U.set_material)=='function' and A.can_get('material',transparent)
                if screen_test then assert(alpha,'weapon screen material unavailable') end
                if alpha then
                    -- Unit asset declares the named slot 'material' (thin hash eac0b497).
                    log('SCENE transparent material assignment begin')
                    U.set_material(unit,'material',transparent)
                end
                local material=Mesh.material(mesh,1)
                local ffi=require('ffi')
                assert(tonumber(ffi.cast('uintptr_t',material))>=65536,'invalid scene material')
                assert(tonumber(ffi.cast('uintptr_t',target))>=65536,'invalid panel texture')
                log('SCENE verified material texture bind begin')
                if screen_test then
                    sr.Material.set_resource(material,'input_image',target)
                    sr.Material.set_scalar(material,'screen_enabled',1)
                    sr.Material.set_vector4(material,'screen_rect',sr.Vector4(side==-1 and 1 or 0,0,side==-1 and -1 or 1,1))
                    sr.Material.set_vector2(material,'Atlas_size',sr.Vector2(1,1))
                    sr.Material.set_vector2(material,'resolution_multiplier',sr.Vector2(1,1))
                    for _,name in ipairs({'normal_map_amount','normal_map_coloring_amount','dirt_amount','distortion_amount','artifacts_amount','light_bleed_amount','use_dropshadow'}) do
                        sr.Material.set_scalar(material,name,0)
                    end
                    log('SCENE weapon screen image bound side='..side..'; appearance unverified')
                else
                sr.Material.set_resource(material,'color_map',target)
                sr.Material.set_resource(material,'emissive_map',target)
                sr.Material.set_scalar(material,'use_color_map',1)
                sr.Material.set_scalar(material,'use_emissive_map',1)
                if side==-1 then
                    sr.Material.set_vector2(material,'uv_scale',sr.Vector2(-1,1))
                    sr.Material.set_vector2(material,'uv_offset',sr.Vector2(1,0))
                end
                scene_material=material
                sr.Material.set_vector3(material,'base_color',sr.Vector3(0,0,0))
                -- Diagnostic: black metallic base removes the dielectric reflection term.
                sr.Material.set_scalar(material,'use_metallic_map',0)
                sr.Material.set_scalar(material,'metallic',1)
                sr.Material.set_scalar(material,'use_roughness_map',0)
                sr.Material.set_scalar(material,'roughness',1)
                sr.Material.set_vector3(material,'emissive',sr.Vector3(1,1,1))
                if alpha then
                    sr.Material.set_scalar(material,'opacity',1)
                    sr.Material.set_scalar(material,'use_opacity_map',1)
                    log('SCENE transparent material bound; alpha pixels unverified')
                end
                end
                scene_material=material
                bound=target
                log('SCENE plane texture bound')
            end
            assert(bound==target,'render target changed without scene retirement')
            if last_emission~=c.emissive_intensity then
                sr.Material.set_scalar(scene_material,screen_test and 'emissive_amount' or 'emissive_intensity',c.emissive_intensity)
                last_emission=c.emissive_intensity
            end
            local m=p.matrix
            local x,y,z=HUD.scene_test.mount(p,c)
            local px=p.x+m[1]*x+m[5]*y+m[9]*z
            local py=p.y+m[2]*x+m[6]*y+m[10]*z
            local pz=p.z+m[3]*x+m[7]*y+m[11]*z
            m=HUD.pose_motion.step(smooth,m,px,py,pz,tostring(p.id)..':'..tostring(p.candidate),dt,c)
            local pose=sr.Matrix4x4.from_axes(sr.Vector3(side*m[1],side*m[2],side*m[3]),sr.Vector3(m[9],m[10],m[11]),sr.Vector3(-side*m[5],-side*m[6],-side*m[7]),sr.Vector3(m[13],m[14],m[15]))
            U.set_local_pose(unit,1,pose)
            U.set_local_scale(unit,1,sr.Vector3(0.24,0.24/math.max(0.25,math.min(8,aspect or 2)),0.24))
        end)
        if not ok then failed=true;log('SCENE stopped '..tostring(err));self.release() end
    end
    return self
end
function M.fullbright(sr,log)
    local gui,world,bound;local stopped=false;local smooth={}
    local A,W,G=sr.Application,sr.World,sr.Gui
    local self={}
    function self.release()
        if gui then
            for _,w in pairs(A.worlds() or {}) do if w==world then W.destroy_gui(world,gui);break end end
        end
        gui,world,bound=nil,nil,nil;smooth={}
    end
    function self.draw(p,c,target,dt,aspect)
        if stopped or not G or not W.create_world_gui then return end
        if not p or not target then self.release();return end
        local ok,err=pcall(function()
            local main=A.main_world()
            if gui and world~=main then self.release() end
            local name='mods/dbf_hud/materials/fullbright_depth_image'
            if not A.can_get('material',name) then return end
            local x,y,z=HUD.scene_test.mount(p,c)
            local m=p.matrix
            local px=p.x+m[1]*x+m[5]*y+m[9]*z
            local py=p.y+m[2]*x+m[6]*y+m[10]*z
            local pz=p.z+m[3]*x+m[7]*y+m[11]*z
            m=HUD.pose_motion.step(smooth,m,px,py,pz,tostring(p.id)..':'..tostring(p.candidate),dt,c)
            local pose=sr.Matrix4x4.from_axes(sr.Vector3(m[1],m[2],m[3]),sr.Vector3(m[5],m[6],m[7]),sr.Vector3(m[9],m[10],m[11]),sr.Vector3(m[13],m[14],m[15]))
            if not gui then
                world=main
                log('FULLBRIGHT main-world GUI create begin')
                gui=assert(W.create_world_gui(world,pose,1000,1000,'immediate'))
                local material=G.material(gui,name)
                local ffi=require('ffi')
                assert(tonumber(ffi.cast('uintptr_t',material))>=65536,'null fullbright material')
                assert(tonumber(ffi.cast('uintptr_t',target))>=65536,'null fullbright target')
                sr.Material.set_resource(material,'diffuse_map',target)
                bound=target
                log('FULLBRIGHT image material bound')
            else G.move(gui,pose) end
            assert(bound==target,'fullbright target changed without cleanup')
            G.bitmap(gui,name,sr.Vector3(-120,-120/(aspect or 2),0),sr.Vector2(240,240/(aspect or 2)),sr.Color(255,255,255,255))
        end)
        if not ok then stopped=true;log('FULLBRIGHT stopped '..tostring(err));pcall(self.release) end
    end
    return self
end
return M

end)()
HUD.scene_test=(function()
-- WorldGUI display selection; archived mesh access remains for research.
local M={}
function M.mount(p,c)
    local x,y,z
    if c.placement_mode=='auto' and p.auto_mount then x,y,z=p.auto_mount.x,p.auto_mount.y,p.auto_mount.z
    elseif p.first_person then x,y,z=c.fp_mount_x,c.fp_mount_y,c.fp_mount_z+.2
    elseif p.left_shoulder then x,y,z=c.left_mount_x,c.left_mount_y,c.left_mount_z+.2
    else x,y,z=c.mount_x,c.mount_y,c.mount_z+.2 end
    return x,y+.0762,z -- Shared three-inch forward shift; Purifier tuned forward and right corrections are external.
end
function M.new(sr,log,side)
    if not side then
        local front,back=M.new(sr,log,1),M.new(sr,log,-1)
        local overlay=HUD.world_probe.new(sr,log,true)
        local depth_overlay=HUD.world_probe.new(sr,log,false)
        local active_mode
        return {
            draw=function(p,c,target,dt,aspect,commands)
                local mode=c.occlusion_mode or (c.hud_occlusion~=false and 'gui_depth' or 'gui')
                if mode=='mesh' then mode='gui_depth' end -- archived selection
                if active_mode~=mode then
                    front.release();back.release();overlay.release();depth_overlay.release()
                    active_mode=mode
                    log('HUD occlusion mode '..mode)
                end
                do
                    if not commands then overlay.release();depth_overlay.release();return end
                    local centered=HUD.world_style.prepare(commands,p,c)
                    if mode=='gui_depth' then return depth_overlay.draw(p,c,centered,dt) else return overlay.draw(p,c,centered,dt) end
                end
            end,
            release=function() overlay.release();depth_overlay.release();front.release();back.release();active_mode=nil end
        }
    end
    return HUD.archived_mesh.new(sr,log,side)
end
function M.fullbright(sr,log)return HUD.archived_mesh.fullbright(sr,log)end
return M

end)()
HUD.texture_art=(function()
-- Optional static artwork replacement. Invalid/unavailable groups retain primitives.
local M={}
local function finite(n)return type(n)=='number' and n==n and math.abs(n)<math.huge end
function M.prepare(commands,resource,available,registry,variant)
    local spec=registry and registry[resource]
    if not spec or spec.version~=1 or type(spec.layers)~='table' then return commands end
    local selected=spec.variants and spec.variants[variant or 'faithful']
    if spec.variants and not selected then return commands end
    local groups={};local materials={}
    for index,base in ipairs(spec.layers)do
        local layer={};for k,v in pairs(base)do layer[k]=v end
        if selected then
            local assets=selected[layer.id];if not assets then return commands end
            layer.material,layer.texture=assets.material,assets.texture
        end
        if type(layer.id)~='string' or type(layer.material)~='string' or type(layer.texture)~='string' or groups[layer.id] or materials[layer.material] then return commands end
        materials[layer.material]=true
        if not available('material',layer.material) or not available('texture',layer.texture) then return commands end
        groups[layer.id]={spec=layer,index=index,members={},minx=math.huge,miny=math.huge,maxx=-math.huge,maxy=-math.huge}
    end
    for i,v in ipairs(commands)do
        local g=groups[v.texture_art_layer]
        if g then
            -- Text, panels, meters, effects and state-driven art must never be tagged.
            if v.type~='rect' or v.texture_art_static~=true or v.fold_child or v.child or v.quad or v.heat_fill or v.charge_meter or v.effect_shader_band or v.scanline_layer or v.fuel_marker_piece then return commands end
            if not finite(v.x) or not finite(v.y) or not finite(v.w) or not finite(v.h) or v.w<=0 or v.h<=0 then return commands end
            if not finite(v.texture_art_opacity) or v.texture_art_opacity<0 or v.texture_art_opacity>1 then return commands end
            if g.opacity and g.opacity~=v.texture_art_opacity then return commands end
            g.opacity=v.texture_art_opacity;g.members[#g.members+1]=i
            if v.texture_art_box then
                local b=v.texture_art_box
                if not finite(b.x) or not finite(b.y) or not finite(b.w) or not finite(b.h) or b.w<=0 or b.h<=0 then return commands end
                if g.box and (g.box.x~=b.x or g.box.y~=b.y or g.box.w~=b.w or g.box.h~=b.h) then return commands end
                g.box=b
            end
            g.minx=math.min(g.minx,v.x);g.miny=math.min(g.miny,v.y);g.maxx=math.max(g.maxx,v.x+v.w);g.maxy=math.max(g.maxy,v.y+v.h)
        end
    end
    local replacements,removed={},{}
    for _,g in pairs(groups)do
        if #g.members==0 or #g.members~=g.spec.command_count then return commands end
        if g.box then
            local b=g.box
            if g.minx<b.x-1e-6 or g.miny<b.y-1e-6 or g.maxx>b.x+b.w+1e-6 or g.maxy>b.y+b.h+1e-6 then return commands end
            g.minx,g.miny,g.maxx,g.maxy=b.x,b.y,b.x+b.w,b.y+b.h
        end
        local bounds=g.spec.aspect
        if not finite(bounds) or bounds<=0 or math.abs((g.maxx-g.minx)/(g.maxy-g.miny)-bounds)>1e-5 then return commands end
        replacements[g.members[1]]={type='texture',x=g.minx,y=g.miny,w=g.maxx-g.minx,h=g.maxy-g.miny,c={255,255,255},a=g.opacity,
            texture_material=g.spec.material,texture_resource=g.spec.texture,texture_art_layer=g.spec.id,texture_layer=49+g.index*.01}
        for _,i in ipairs(g.members)do removed[i]=true end
    end
    local out={}
    for i,v in ipairs(commands)do if replacements[i] then out[#out+1]=replacements[i] elseif not removed[i] then out[#out+1]=v end end
    return out
end
return M

end)()
HUD.texture_art_assets=(function()
