HUD.runtime_textures=(function()
-- Queued immutable uploads. The adapter owns native contracts and render phase.
local M={max_image_bytes=4194304,max_retained_bytes=33554432}
local function dimensions(image)
    assert(type(image)=='table' and image.format=='RGBA8','RGBA8 image required')
    for _,key in ipairs({'width','height'}) do
        local n=image[key];assert(type(n)=='number' and n==n and n>=1 and n%1==0 and n<=1024,'invalid image dimensions')
    end
    local count=image.width*image.height*4
    assert(count<=M.max_image_bytes and image.row_pitch==image.width*4,'invalid image pitch')
    return count
end
function M.validate(image)
    local count=dimensions(image)
    assert(type(image.rgba)=='string' and #image.rgba==count,'invalid pixel length')
    return count
end
local function snapshot(image)
    return {format=image.format,width=image.width,height=image.height,row_pitch=image.row_pitch,rgba=image.rgba,path=image.path}
end
function M.read_image(path,width,height)
    assert(type(path)=='string' and not path:find('%z'),'invalid image path')
    assert(type(width)=='number','invalid image width')
    local count=dimensions({format='RGBA8',width=width,height=height,row_pitch=width*4})
    local f=assert(io.open(path,'rb'),'image file unavailable')
    local pixels=f:read(count+1);f:close()
    local image={format='RGBA8',width=width,height=height,row_pitch=width*4,rgba=pixels,path=path}
    M.validate(image);return image
end
function M.new(adapter,store)
    store=store or {bytes=0,resources={},claims={}}
    local self={targets={},closing=false,status='idle'}
    local function valid(t)return adapter.valid(t.native)==true end
    local function retain(image)
        local size=M.validate(image)
        assert(store.bytes+size<=M.max_retained_bytes,'retained texture budget exhausted; restart required')
        -- Reserve first: failed native uploads can still have queued GPU work.
        store.bytes=store.bytes+size
        local record={bytes=size};store.resources[#store.resources+1]=record
        adapter.upload(image,record)
        assert(record.resource,'upload did not return an owned resource')
        return record
    end
    function self.register(id,native,original)
        assert(not self.closing and type(id)=='string' and id~='' and not self.targets[id],'invalid target')
        assert(not store.claims[id],'target still owned by another instance')
        M.validate(original);if adapter.validate_image then adapter.validate_image(native,original)end
        assert(adapter.valid(native)==true,'target identity unavailable')
        self.targets[id]={native=native,original_image=snapshot(original),width=original.width,height=original.height}
        store.claims[id]=self
        return true
    end
    function self.swap(id,image)
        assert(not self.closing,'texture manager retiring')
        local t=assert(self.targets[id],'unknown texture target');M.validate(image)
        assert(image.width==t.width and image.height==t.height,'replacement dimensions differ')
        if adapter.validate_image then adapter.validate_image(t.native,image)end
        if t.active and not t.restore and t.current_image and t.current_image.rgba==image.rgba then
            t.file=image.path or t.file;return true
        end
        t.pending=snapshot(image);t.restore=false;return true -- Coalesce before allocation.
    end
    function self.restore(id)
        local t=assert(self.targets[id],'unknown texture target');t.pending=nil;t.restore=true;return true
    end
    function self.reload_files()
        for id,t in pairs(self.targets) do
            if t.file then self.swap(id,M.read_image(t.file,t.width,t.height)) end
        end
        return true
    end
    function self.close()
        self.closing=true
        for _,t in pairs(self.targets)do t.pending=nil;t.restore=true end
    end
    function self.step()
        assert(adapter.in_render_phase()==true,'texture work requires render bridge')
        local complete=true
        for id,t in pairs(self.targets)do
            local ok,err=pcall(function()
                if not t.pending and not (t.restore and t.active) then t.restore=false;return end
                if not valid(t) then
                    -- Retired units cannot be restored through stale pointers.
                    t.pending=nil;t.restore=false;t.active=false;t.retired=true
                elseif t.restore then
                    if t.active then
                        adapter.bind(t.native,assert(t.original).resource)
                        t.active=false;t.current_image=nil;self.status='original pixels restored; visible result requires verification'
                    end
                    t.restore=false
                elseif t.pending then
                    local image=t.pending;t.pending=nil
                    assert(store.bytes+M.validate(image)+(t.original and 0 or M.validate(t.original_image))<=M.max_retained_bytes,'retained texture budget exhausted; restart required')
                    if not t.original then t.original=retain(t.original_image) end
                    local candidate=retain(image)
                    -- Mark before binding: a refresh may fail after set_resource.
                    t.active=true;t.candidate=candidate;t.file=image.path
                    adapter.bind(t.native,candidate.resource)
                    t.current_image=image
                    self.status='submitted; visible result requires verification'
                end
            end)
            if not ok then
                self.status=tostring(err)
                if t.active then t.restore=true end
            end
            if self.closing then
                if t.active or t.restore then complete=false
                elseif store.claims[id]==self then store.claims[id]=nil end
            end
        end
        return self.closing and complete
    end
    function self.stats()return {retained_bytes=store.bytes,retained_resources=#store.resources,status=self.status}end
    return self
end
return M

end)()
HUD.runtime_texture_native=(function()
-- Native support is opt-in and limited to the measured game/API contracts.
local M={}
local function unhex(s)return(s:gsub('..',function(v)return string.char(tonumber(v,16))end))end
local contracts={
    create_resource='488bd1e9a8fbffffcccccccccccccccc',
    update_texture_base64='48895c240848896c2410488974241848',
    set_resource='48895c24184889742420574883ec20ba',
    refresh_instance_hash='4883ec28ba01000000ff15b9eff60048'
}
function M.new(sr,backend)
    local ffi=require('ffi');local util=require('jit.util')
    local function read(address,count)
        assert(type(address)=='number' and address>65535 and address+count<2^47 and count<=4096,'invalid native span')
        return assert(backend.read(address,count),'native span unreadable')
    end
    local function u32(bytes,offset)local b=ffi.new('uint8_t[?]',#bytes,bytes);return tonumber(ffi.cast('uint32_t*',b+offset)[0])end
    local function ptr(bytes,offset)local b=ffi.new('uint8_t[?]',#bytes,bytes);return tonumber(ffi.cast('uintptr_t*',b+offset)[0])end
    local module=assert(backend.module('helldivers2.exe'),'game module unavailable')
    local pe=read(module+u32(read(module,64),60),12)
    assert(pe:sub(1,4)=='PE\0\0' and u32(pe,8)==0x6ab382e4,'unverified game build')
    local apis={create_resource=sr.Renderer.create_resource,update_texture_base64=sr.Renderer.update_texture_base64,
        set_resource=sr.Material.set_resource,refresh_instance_hash=sr.Mesh.refresh_instance_hash}
    for name,fn in pairs(apis) do
        local address=assert(tonumber(util.funcinfo(assert(fn)).addr),'native API required')
        assert(read(address,16)==unhex(contracts[name]),'unverified native API: '..name)
    end
    local phase=false
    local self={}
    function self.set_phase(value)phase=value==true end
    function self.in_render_phase()return phase end
    local function texture(resource,width,height)
        assert(type(resource)=='userdata','factory userdata required')
        local address=tonumber(ffi.cast('uintptr_t',resource));local h=read(address,64)
        assert(h:byte(4)==0 and u32(h,8)==0 and u32(h,20)==width and u32(h,24)==height and u32(h,28)==1,'unexpected owned texture')
        assert(u32(h,48)==1 and u32(h,52)>=1,'unexpected owned backing array')
        local backing=ptr(read(ptr(h,56),8),0)
        return address,backing
    end
    local alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
    local function prefix64(bytes)
        local a,b,c,d=bytes:byte(1,4);local n=a*65536+b*256+c
        local function at(i)return alphabet:sub(i+1,i+1)end
        return at(math.floor(n/262144)%64)..at(math.floor(n/4096)%64)..at(math.floor(n/64)%64)..at(n%64)..at(math.floor(d/4))..at((d%4)*16)..'=='
    end
    function self.upload(image,record)
        assert(phase,'upload outside render bridge')
        for _,key in ipairs({'width','height'})do
            local n=image[key];assert(type(n)=='number' and n>=1 and n<=1024 and n%1==0,'invalid upload dimensions')
        end
        assert(image.format=='RGBA8' and image.row_pitch==image.width*4 and type(image.rgba)=='string' and #image.rgba==image.width*image.height*4,'invalid upload bytes')
        record.resource=assert(sr.Renderer.create_resource('texture','R8G8B8A8',image.width,image.height))
        local address,backing=texture(record.resource,image.width,image.height)
        local count=#image.rgba
        for offset=0,count-1,4096 do read(backing+offset,math.min(4096,count-offset))end
        local current_address,current_backing=texture(record.resource,image.width,image.height)
        assert(address==current_address and backing==current_backing,'owned allocation identity changed')
        ffi.copy(ffi.cast('void*',backing),image.rgba,count)
        for offset=0,count-1,4096 do
            local size=math.min(4096,count-offset)
            assert(read(backing+offset,size)==image.rgba:sub(offset+1,offset+size),'pixel readback differs')
        end
        record.address=address;record.backing=backing
        -- Native decoder has a small stack buffer. Never pass the whole image.
        sr.Renderer.update_texture_base64(record.resource,prefix64(image.rgba),4)
    end
    function self.target(spec)
        assert(type(spec)=='table' and (spec.kind=='world_mesh' or spec.kind=='scope'),'unsupported texture target kind')
        assert(type(spec.unit)=='userdata' and type(spec.unit_resource)=='string' and #spec.unit_resource==16 and spec.unit_resource:match('^[0-9a-f]+$'),'verified unit required')
        assert(type(spec.material_id)=='string' and spec.material_id:match('^[0-9a-f]+$') and #spec.material_id==16,'material identity required')
        assert(type(spec.texture_slot)=='string' and ({emissive_map=true,lens_occlusion_texture=true,reticle_texture=true,artwork_texture=true})[spec.texture_slot],'unverified texture slot')
        assert(type(spec.meshes)=='table' and #spec.meshes>=1 and #spec.meshes<=16,'mesh list required')
        assert(type(spec.material_slot)=='string' and #spec.material_slot==8 and spec.material_slot:match('^[0-9a-f]+$'),'material slot required')
        local t={kind=spec.kind,unit=spec.unit,unit_resource=spec.unit_resource,material_id=spec.material_id,
            texture_slot=spec.texture_slot,material_slot=spec.material_slot,meshes={}}
        for i,v in ipairs(spec.meshes)do assert(type(v)=='number' and v%1==0 and v>=1 and v<=256,'invalid mesh');t.meshes[i]=v end
        return t
    end
    local function resolve(t)
        local found,total=false,0
        for _,world in pairs(sr.Application.worlds())do for _,unit in pairs(sr.World.units(world))do
            total=total+1;assert(total<=32768,'unit inventory exceeds bound')
            if unit==t.unit then found=sr.IdString64.to_hex(sr.Unit.resource_name(unit)):lower()==t.unit_resource end
        end end
        if not found then return nil end
        local material,meshes=nil,{}
        local count=sr.Unit.num_meshes(t.unit)
        for _,index in ipairs(t.meshes)do
            if index>count then return nil end
            local mesh=sr.Unit.mesh(t.unit,index);if not mesh then return nil end
            local matched=false;local slots=sr.Mesh.num_materials(mesh);if slots>128 then return nil end
            for j=1,slots do
                if sr.IdString32.to_hex(sr.Mesh.material_slot_id(mesh,j)):lower()==t.material_slot then
                    local h=sr.Mesh.material(mesh,j);if not h then return nil end
                    -- Mesh.material returns the direct pointer; Unit.set_material does not.
                    local header=read(tonumber(ffi.cast('uintptr_t',h)),64)
                    if u32(header,0)==0x6f6f4d64 then return nil end
                    if sr.IdString64.to_hex(sr.Material.id64(h)):lower()~=t.material_id then return nil end
                    if material and material~=h then return nil end
                    material=h;matched=true
                end
            end
            if not matched then return nil end;meshes[#meshes+1]=mesh
        end
        return material,meshes
    end
    function self.valid(t)return resolve(t)~=nil end
    function self.validate_image(t,image)
        if t.texture_slot=='lens_occlusion_texture' then
            for i=1,#image.rgba,4 do
                local _,g,b,a=image.rgba:byte(i,i+3)
                assert(g==0 and b==0 and a==255,'lens mask requires R,0,0,255 pixels')
            end
        end
    end
    function self.bind(t,resource)
        assert(phase,'binding outside render bridge')
        local material,meshes=resolve(t);assert(material,'target retired or identity changed')
        sr.Material.set_resource(material,t.texture_slot,resource)
        if t.kind=='world_mesh' then for _,mesh in ipairs(meshes)do sr.Mesh.refresh_instance_hash(mesh)end end
    end
    return self
end
return M

end)()
HUD.runtime_texture_bridge=(function()
-- No native work until an explicit registration/swap request.
local M={}
function M.new(sr,backend)
    local bridge=assert(rawget(_G,'HUDRenderBridge'),'render bridge unavailable')
    assert(bridge.api==1 and type(bridge.subscribe)=='function','verified render bridge required')
    local native=HUD.runtime_texture_native.new(sr,backend)
    local key='dbf_hud.runtime_texture_lifetime.v1'
    local store=package.loaded[key]
    if not store then store={bytes=0,resources={},claims={},serial=0};package.loaded[key]=store end
    store.serial=store.serial+1
    local manager=HUD.runtime_textures.new(native,store)
    local unsubscribe
    unsubscribe=bridge.subscribe('dbf_hud.runtime_textures.'..store.serial,function()
        native.set_phase(true)
        local ok,complete=pcall(manager.step)
        native.set_phase(false)
        if not ok then manager.status=tostring(complete)end
        if ok and complete==true and unsubscribe then local off=unsubscribe;unsubscribe=nil;off()end
    end)
    local self={}
    function self.register(id,spec,original)
        return manager.register(id,native.target(spec),original)
    end
    self.image=HUD.runtime_textures.read_image
    function self.swap_file(id,path)
        local t=assert(manager.targets[id],'unknown texture target')
        return manager.swap(id,HUD.runtime_textures.read_image(path,t.width,t.height))
    end
    self.swap=manager.swap;self.restore=manager.restore;self.reload_files=manager.reload_files
    self.close=manager.close;self.stats=manager.stats
    return self
end
return M

end)()
HUD.hot_panel_art=(function()
-- File-backed HUD artwork; uploads run only on the render bridge.
local M={}
function M.new(sr,backend,root)
 local self={pending={},active={},status='No hot artwork loaded',closing=false}
 local native,off
 local key='dbf_hud.hot_panel_art.lifetime.v1'
 local store=package.loaded[key] or {bytes=0,resources={}};package.loaded[key]=store
 local function initialize()
  if native then return end
  local bridge=assert(rawget(_G,'HUDRenderBridge'),'render bridge unavailable')
  assert(bridge.api==1,'verified render bridge required')
  native=HUD.runtime_texture_native.new(sr,backend)
  off=bridge.subscribe('dbf_hud.hot_panel_art.'..tostring(self),function()
   if not self.closing and next(self.pending)==nil then return end
   native.set_phase(true)
   local ok,err=pcall(function()
    if self.closing then self.pending={};self.active={};return end
    for name,image in pairs(self.pending)do
     self.pending[name]=nil
     local prior=self.active[name]
     if not prior or prior.rgba~=image.rgba then
      local size=HUD.runtime_textures.validate(image)
      assert(store.bytes+size<=HUD.runtime_textures.max_retained_bytes,'Hot artwork budget exhausted; restart required')
      local record={bytes=size,rgba=image.rgba};store.bytes=store.bytes+size;store.resources[#store.resources+1]=record
      native.upload(image,record);self.active[name]=record
     end
    end
    self.status='Hot artwork uploaded; verify appearance'
   end)
   native.set_phase(false)
   if not ok then self.status=tostring(err)end
   if self.closing and off then local stop=off;off=nil;stop()end
  end)
 end
 function self.reload()
  local f=assert(io.open(root..'/manifest.tsv','rb'),'Hot artwork manifest missing')
  local text=f:read(65537);f:close();assert(#text<=65536,'Manifest too large')
  local queue={};local count=0
  for line in text:gmatch('[^\r\n]+')do
   if line:sub(1,1)~='#' then
    local name,w,h=line:match('^([%w_%-]+)\t(%d+)\t(%d+)$');assert(name,'Invalid artwork manifest row')
    assert(not queue[name],'Duplicate artwork');count=count+1;assert(count<=512,'Too many artwork entries')
    queue[name]=HUD.runtime_textures.read_image(root..'/'..name..'.rgba',tonumber(w),tonumber(h))
   end
  end
  assert(count>0,'Manifest has no artwork');initialize();self.pending=queue
  self.status='Queued '..count..' artwork files';return self.status
 end
 function self.resource(texture)
  if self.closing then return nil end
  local name=texture and texture:match('^mods/dbf_hud/textures/([%w_%-]+)$')
  return name and self.active[name] and self.active[name].resource
 end
 function self.restore()self.pending={};self.active={};self.status='Packaged artwork restored';return self.status end
 function self.close()self.closing=true;self.pending={};self.active={}end
 return self
end
return M

end)()
