   for _,dy in ipairs({0,1-tick})do out[#out+1]={type='rect',x=lx+zw*i/20,y=ly+zh*dy,w=math.max(.3*s,zw*.0025),h=zh*tick,c=loaded and {18,23,24}or {113,126,129},a=.8*opacity,mechanical_live=true}end
